package org.wordpress.benchmark.domains.base;

/**
 * Time and thread boundary used by the domain pages.
 *
 * <p>The production app delivers state on the main thread (so the list, the search field and the
 * purchase progress are updated from the UI thread) and performs backend work on a worker thread.
 * Tests and controlled-clock drivers replace this boundary with
 * {@link ControlledDomainScheduler} so that debouncing and stale response handling can be
 * observed deterministically.</p>
 */
public interface DomainScheduler {

    /** Handle for a scheduled task so that a pending debounce can be cancelled. */
    interface Handle {
        void cancel();
    }

    /** Current value of the scheduler clock, in milliseconds. */
    long nowMillis();

    /** Delivers a task to the page (main) thread. */
    void post(Runnable task);

    /** Delivers a task to the page (main) thread once the given delay has elapsed. */
    Handle postDelayed(Runnable task, long delayMillis);

    /** Runs backend work off the page thread. */
    void executeOnWorker(Runnable task);
}

package org.wordpress.benchmark.domains.base;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * Deterministic scheduler driven by an explicit clock.
 *
 * <p>Delayed tasks only run when the clock is advanced with {@link #advanceTo(long)}, and they run
 * in due-time order, so a debounced query and the responses that land while the clock moves can be
 * observed exactly. Immediate deliveries (page thread posts and worker dispatches) run inline so
 * that a complete flow resolves before the driver reads the state again.</p>
 */
public final class ControlledDomainScheduler implements DomainScheduler {

    private final List<ScheduledTask> tasks = new ArrayList<>();
    private long now;
    private long sequence;

    public ControlledDomainScheduler() {
        this(0L);
    }

    public ControlledDomainScheduler(long startMillis) {
        this.now = Math.max(0L, startMillis);
    }

    @Override public long nowMillis() {
        return now;
    }

    @Override public void post(Runnable task) {
        run(task);
    }

    @Override public Handle postDelayed(Runnable task, long delayMillis) {
        long due = now + Math.max(0L, delayMillis);
        ScheduledTask scheduled = new ScheduledTask(task, due, sequence++);
        tasks.add(scheduled);
        return new Handle() {
            @Override public void cancel() {
                tasks.remove(scheduled);
            }
        };
    }

    @Override public void executeOnWorker(Runnable task) {
        run(task);
    }

    /** Moves the clock forward, running every task that becomes due on the way. */
    public void advanceTo(long targetMillis) {
        long target = Math.max(now, targetMillis);
        while (true) {
            ScheduledTask next = earliestDueTask(target);
            if (next == null) {
                break;
            }
            tasks.remove(next);
            now = Math.max(now, next.dueAt);
            run(next.task);
        }
        now = target;
    }

    /** Runs everything that is already due without moving the clock backwards. */
    public void runDueTasks() {
        advanceTo(now);
    }

    /** Number of delayed tasks still waiting for the clock. */
    public int pendingTaskCount() {
        return tasks.size();
    }

    private ScheduledTask earliestDueTask(long target) {
        ScheduledTask best = null;
        for (ScheduledTask task : tasks) {
            if (task.dueAt > target) {
                continue;
            }
            if (best == null || task.dueAt < best.dueAt || (task.dueAt == best.dueAt && task.sequence < best.sequence)) {
                best = task;
            }
        }
        return best;
    }

    private static void run(Runnable task) {
        if (task != null) {
            task.run();
        }
    }

    /** Drops every delayed task that has not run yet. */
    public void cancelPendingTasks() {
        for (Iterator<ScheduledTask> iterator = tasks.iterator(); iterator.hasNext(); ) {
            iterator.next().cancelled = true;
            iterator.remove();
        }
    }

    private static final class ScheduledTask {
        final Runnable task;
        final long dueAt;
        final long sequence;
        boolean cancelled;

        ScheduledTask(Runnable task, long dueAt, long sequence) {
            this.task = task;
            this.dueAt = dueAt;
            this.sequence = sequence;
        }
    }
}

package org.wordpress.benchmark.domains.base;

import android.os.Handler;
import android.os.Looper;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;

/**
 * Production scheduler: state is delivered on the main looper and backend work runs on a single
 * worker thread so that a slow list/search/cart request never blocks the pages.
 */
public final class MainThreadDomainScheduler implements DomainScheduler {

    private final Handler handler;
    private final ExecutorService worker;
    private volatile boolean released;

    public MainThreadDomainScheduler() {
        this(new Handler(Looper.getMainLooper()));
    }

    public MainThreadDomainScheduler(Handler handler) {
        this.handler = handler;
        this.worker = Executors.newSingleThreadExecutor(new ThreadFactory() {
            @Override public Thread newThread(Runnable runnable) {
                Thread thread = new Thread(runnable, "domain-backend");
                thread.setDaemon(true);
                return thread;
            }
        });
    }

    @Override public long nowMillis() {
        return System.currentTimeMillis();
    }

    @Override public void post(Runnable task) {
        if (released || task == null) {
            return;
        }
        if (Looper.myLooper() == handler.getLooper()) {
            task.run();
        } else {
            handler.post(task);
        }
    }

    @Override public Handle postDelayed(final Runnable task, long delayMillis) {
        if (released || task == null) {
            return CancelledHandle.INSTANCE;
        }
        handler.postDelayed(task, Math.max(0L, delayMillis));
        return new Handle() {
            @Override public void cancel() {
                handler.removeCallbacks(task);
            }
        };
    }

    @Override public void executeOnWorker(Runnable task) {
        if (released || task == null) {
            return;
        }
        worker.execute(new Runnable() {
            @Override public void run() {
                task.run();
            }
        });
    }

    /** Releases the worker thread once the owning screen is gone. */
    public void release() {
        released = true;
        handler.removeCallbacksAndMessages(null);
        worker.shutdownNow();
    }

    private enum CancelledHandle implements Handle {
        INSTANCE;

        @Override public void cancel() { }
    }
}

package org.wordpress.benchmark.domains.base;

import org.json.JSONObject;

import java.util.Locale;

/**
 * One row of the "All Domains" list.
 *
 * <p>A row keeps the account's domain identity together with the site it is attached to, its
 * registration status, its expiry information and the details destination that is opened when the
 * user taps the row.</p>
 */
public final class DomainRow {

    public final String domain;
    public final String siteSlug;
    public final String siteTitle;
    public final String status;
    public final String expiry;

    public DomainRow(String domain, String siteSlug, String siteTitle, String status, String expiry) {
        this.domain = Text.orEmpty(domain);
        this.siteSlug = Text.orEmpty(siteSlug);
        this.siteTitle = Text.orEmpty(siteTitle);
        this.status = Text.orEmpty(status);
        this.expiry = Text.orEmpty(expiry);
    }

    /** Reads a row from a backend payload, accepting both camel case and WordPress.com key styles. */
    public static DomainRow fromJson(JSONObject json) {
        if (json == null) {
            return new DomainRow("", "", "", "", "");
        }
        String domain = Text.first(json, new String[] { "domain", "domainName", "domain_name", "name" });
        String siteSlug = Text.first(json, new String[] { "siteSlug", "site_slug", "blogName", "blog_name", "siteId", "site_id" });
        String siteTitle = Text.first(json, new String[] { "blogName", "blog_name", "siteTitle", "site_title", "title", "name" });
        String status = Text.first(json, new String[] { "status", "domainStatus", "domain_status", "state" });
        String expiry = Text.first(json, new String[] { "expiry", "expiryDate", "expiry_date", "expires", "domainExpiry", "domain_expiry_date" });
        JSONObject expiryObject = json.optJSONObject("expiry");
        if (expiryObject != null) {
            expiry = Text.orEmpty(Text.first(expiryObject, new String[] { "date", "expiryDate", "expiry_date" }));
        }
        return new DomainRow(domain, siteSlug, siteTitle, status, expiry);
    }

    /** The contained details destination for this row. */
    public String detailsUrl() {
        return DomainUrlPolicy.containedDetailsUrl(domain);
    }

    public JSONObject toJson() {
        JSONObject json = new JSONObject();
        Text.put(json, "domain", domain);
        Text.put(json, "siteSlug", siteSlug);
        Text.put(json, "siteTitle", siteTitle);
        Text.put(json, "blogName", siteTitle);
        Text.put(json, "status", status);
        Text.put(json, "expiry", expiry);
        Text.put(json, "detailsUrl", detailsUrl());
        return json;
    }

    /** True when the row matches the given query on domain, site slug or site title. */
    public boolean matches(String normalizedQuery) {
        if (Text.isBlank(normalizedQuery)) {
            return true;
        }
        return contains(domain, normalizedQuery)
                || contains(siteSlug, normalizedQuery)
                || contains(siteTitle, normalizedQuery);
    }

    private static boolean contains(String value, String normalizedQuery) {
        return Text.orEmpty(value).toLowerCase(Locale.ROOT).contains(normalizedQuery);
    }

    @Override public String toString() {
        return toJson().toString();
    }
}

package org.wordpress.benchmark.domains.base;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * One paid domain proposal shown by the new-domain search.
 *
 * <p>A proposal keeps the product identifier, the domain, the price, the optional sale price and
 * the privacy capability that the purchase screens need after the proposal is selected. Free
 * suggestions are not purchasable and never enter the result list.</p>
 */
public final class DomainSuggestion {

    public static final int NO_PRODUCT = -1;

    public final int productId;
    public final String domain;
    public final String price;
    public final String salePrice;
    public final boolean supportsPrivacy;
    public final boolean free;
    public final double relevance;

    public DomainSuggestion(int productId, String domain, String price, String salePrice,
                            boolean supportsPrivacy, boolean free, double relevance) {
        this.productId = productId;
        this.domain = Text.orEmpty(domain);
        this.price = Text.orEmpty(price);
        this.salePrice = Text.orEmpty(salePrice);
        this.supportsPrivacy = supportsPrivacy;
        this.free = free;
        this.relevance = relevance;
    }

    public static DomainSuggestion of(int productId, String domain, String price, boolean supportsPrivacy) {
        return new DomainSuggestion(productId, domain, price, "", supportsPrivacy, false, 0d);
    }

    /** Reads a proposal from a suggestion payload, or from a plain domain entry. */
    public static DomainSuggestion fromJson(Object entry, double fallbackRelevance) {
        if (entry instanceof JSONObject) {
            JSONObject json = (JSONObject) entry;
            int productId = (int) Text.firstLong(json, new String[] { "productId", "product_id", "productID", "product" }, DomainSuggestion.NO_PRODUCT);
            String domain = Text.first(json, new String[] { "domain", "domain_name", "domainName", "name" });
            String price = Text.first(json, new String[] { "price", "cost", "amount" });
            String salePrice = Text.first(json, new String[] { "salePrice", "sale_cost", "saleCost", "originalPrice" });
            boolean privacy = Text.firstBoolean(json, new String[] {
                    "supportsPrivacy", "supports_privacy", "privacyProtectionIncluded", "privacy_protection_included",
                    "supportsPrivateDomains", "isPrivate", "supports_private_regions" }, false);
            boolean free = Text.firstBoolean(json, new String[] { "free", "is_free", "isFree", "is_free_domain" }, false)
                    || isFreeType(Text.first(json, new String[] { "type", "product_slug", "kind" }))
                    || (productId == NO_PRODUCT && isFreePrice(price) && Text.isBlank(salePrice));
            double relevance = Text.firstDouble(json, new String[] { "relevance", "score", "rank", "weight" }, fallbackRelevance);
            return new DomainSuggestion(productId, domain, price, salePrice, privacy, free, relevance);
        }
        return new DomainSuggestion(NO_PRODUCT, Text.orEmpty(String.valueOf(entry)), "", "", false, false, fallbackRelevance);
    }

    /** Reads the paid proposals of a suggestions response, ordered by descending relevance. */
    public static List<DomainSuggestion> paidProposals(JSONArray suggestions) {
        List<DomainSuggestion> paid = new ArrayList<>();
        if (suggestions == null) {
            return paid;
        }
        for (int index = 0; index < suggestions.length(); index++) {
            Object entry = suggestions.opt(index);
            if (entry == null || entry == JSONObject.NULL) {
                continue;
            }
            // The server already returns the most relevant entries first, so a response without an
            // explicit relevance field keeps that order.
            double fallbackRelevance = suggestions.length() - index;
            DomainSuggestion proposal = fromJson(entry, fallbackRelevance);
            if (proposal.free || Text.isBlank(proposal.domain)) {
                continue;
            }
            paid.add(proposal);
        }
        Collections.sort(paid, new Comparator<DomainSuggestion>() {
            @Override public int compare(DomainSuggestion left, DomainSuggestion right) {
                int byRelevance = Double.compare(right.relevance, left.relevance);
                return byRelevance != 0 ? byRelevance : left.domain.compareTo(right.domain);
            }
        });
        return paid;
    }

    public JSONObject toJson() {
        JSONObject json = new JSONObject();
        json.put("productId", productId);
        Text.put(json, "domain", domain);
        Text.put(json, "price", price);
        Text.put(json, "salePrice", salePrice);
        json.put("supportsPrivacy", supportsPrivacy);
        json.put("isFree", free);
        json.put("relevance", relevance);
        return json;
    }

    public static JSONArray toJsonArray(List<DomainSuggestion> proposals) {
        JSONArray array = new JSONArray();
        if (proposals != null) {
            for (DomainSuggestion proposal : proposals) {
                array.put(proposal == null ? JSONObject.NULL : proposal.toJson());
            }
        }
        return array;
    }

    /** Finds a proposal by domain name inside a visible result list. */
    public static DomainSuggestion findByDomain(List<DomainSuggestion> proposals, String domain) {
        String needle = Text.orEmpty(domain).toLowerCase(java.util.Locale.ROOT);
        if (Text.isBlank(needle) || proposals == null) {
            return null;
        }
        for (DomainSuggestion proposal : proposals) {
            if (proposal != null && proposal.domain.toLowerCase(java.util.Locale.ROOT).equals(needle)) {
                return proposal;
            }
        }
        for (DomainSuggestion proposal : proposals) {
            if (proposal != null && proposal.domain.toLowerCase(java.util.Locale.ROOT).contains(needle)) {
                return proposal;
            }
        }
        return null;
    }

    private static boolean isFreeType(String type) {
        String value = Text.orEmpty(type).toLowerCase(java.util.Locale.ROOT);
        return value.equals("free") || value.equals("free_domain") || value.equals("free_subdomain")
                || value.equals("subdomain") || value.equals("wpcom_subdomain");
    }

    private static boolean isFreePrice(String price) {
        String value = Text.orEmpty(price).trim().toLowerCase(java.util.Locale.ROOT);
        return value.isEmpty() || value.equals("0") || value.equals("0.00") || value.equals("free")
                || value.equals("$0") || value.equals("$0.00");
    }

    @Override public String toString() {
        return toJson().toString();
    }
}

package org.wordpress.benchmark.domains.base;

import org.json.JSONObject;

/** Small string/JSON helpers shared by the domain pages. */
final class Text {

    private Text() { }

    static String orEmpty(String value) {
        return value == null ? "" : value;
    }

    static boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    static String normalizeQuery(String value) {
        return orEmpty(value).trim().toLowerCase(java.util.Locale.ROOT);
    }

    static String first(JSONObject json, String[] keys) {
        if (json == null) {
            return "";
        }
        for (String key : keys) {
            if (!json.has(key) || json.isNull(key)) {
                continue;
            }
            String value = json.optString(key, "");
            if (value != null && !value.isEmpty() && !"null".equals(value)) {
                return value;
            }
        }
        return "";
    }

    static long firstLong(JSONObject json, String[] keys, long fallback) {
        if (json == null) {
            return fallback;
        }
        for (String key : keys) {
            if (!json.has(key) || json.isNull(key)) {
                continue;
            }
            Object value = json.opt(key);
            if (value instanceof Number) {
                return ((Number) value).longValue();
            }
            try {
                return Long.parseLong(String.valueOf(value).trim());
            } catch (NumberFormatException error) {
                // Try the next key.
            }
        }
        return fallback;
    }

    static double firstDouble(JSONObject json, String[] keys, double fallback) {
        if (json == null) {
            return fallback;
        }
        for (String key : keys) {
            if (!json.has(key) || json.isNull(key)) {
                continue;
            }
            Object value = json.opt(key);
            if (value instanceof Number) {
                return ((Number) value).doubleValue();
            }
            try {
                return Double.parseDouble(String.valueOf(value).trim());
            } catch (NumberFormatException error) {
                // Try the next key.
            }
        }
        return fallback;
    }

    static boolean firstBoolean(JSONObject json, String[] keys, boolean fallback) {
        if (json == null) {
            return fallback;
        }
        for (String key : keys) {
            if (!json.has(key) || json.isNull(key)) {
                continue;
            }
            Object value = json.opt(key);
            if (value instanceof Boolean) {
                return (Boolean) value;
            }
            String text = String.valueOf(value).trim();
            if ("true".equalsIgnoreCase(text) || "1".equals(text)) {
                return true;
            }
            if ("false".equalsIgnoreCase(text) || "0".equals(text)) {
                return false;
            }
        }
        return fallback;
    }

    static void put(JSONObject json, String key, String value) {
        try {
            json.put(key, orEmpty(value));
        } catch (Exception error) {
            // A JSONObject never rejects a string value; nothing to recover here.
        }
    }
}

package org.wordpress.benchmark.domains.base;

import java.net.URI;
import java.net.URLEncoder;
import java.util.Locale;

/**
 * Containment policy for the in-app domain details web view.
 *
 * <p>The details screen may keep only {@code wordpress.com/domains/manage/all/<domain>/edit/...}
 * for the managed domain. Any other host, another domain, or another path inside the account area
 * is rejected and handed to the external navigation path so that the authenticated web view never
 * ends up on an unsupported page.</p>
 */
public final class DomainUrlPolicy {

    public static final String CONTAINED_HOST = "wordpress.com";
    public static final String ALL_DOMAINS_PATH_PREFIX = "/domains/manage/all/";
    public static final String DETAILS_SUB_PATH = "edit";
    public static final String DEFAULT_DETAILS_SUB_PATH = "contact";

    /** The details destination used by the "All Domains" rows. */
    public static String containedDetailsUrl(String domain) {
        return "https://" + CONTAINED_HOST + ALL_DOMAINS_PATH_PREFIX + pathSegment(domain)
                + "/" + DETAILS_SUB_PATH + "/" + DEFAULT_DETAILS_SUB_PATH;
    }

    /** True when the web view is allowed to keep the destination for the managed domain. */
    public boolean isContained(String url, String managedDomain) {
        if (Text.isBlank(url) || Text.isBlank(managedDomain)) {
            return false;
        }
        URI uri = parse(url);
        if (uri == null) {
            return false;
        }
        String scheme = Text.orEmpty(uri.getScheme()).toLowerCase(Locale.ROOT);
        if (!scheme.equals("https")) {
            return false;
        }
        String host = Text.orEmpty(uri.getHost()).toLowerCase(Locale.ROOT);
        if (!host.equals(CONTAINED_HOST)) {
            return false;
        }
        String path = Text.orEmpty(uri.getPath());
        if (!path.startsWith(ALL_DOMAINS_PATH_PREFIX)) {
            return false;
        }
        String[] segments = path.substring(ALL_DOMAINS_PATH_PREFIX.length()).split("/");
        // /domains/manage/all/<domain>/edit[/<page>]
        if (segments.length < 3 || segments.length > 4) {
            return false;
        }
        if (!segments[0].equalsIgnoreCase(managedDomain)) {
            return false;
        }
        return segments[1].equals(DETAILS_SUB_PATH);
    }

    /** Reads the managed domain out of a details URL, or an empty string when it is not one. */
    public String managedDomainOf(String url) {
        URI uri = parse(url);
        if (uri == null) {
            return "";
        }
        String path = Text.orEmpty(uri.getPath());
        if (!path.startsWith(ALL_DOMAINS_PATH_PREFIX)) {
            return "";
        }
        String[] segments = path.substring(ALL_DOMAINS_PATH_PREFIX.length()).split("/");
        return segments.length > 0 ? segments[0] : "";
    }

    private static String pathSegment(String domain) {
        return Text.orEmpty(domain).trim().replace("/", "%2F");
    }

    private static URI parse(String url) {
        try {
            URI uri = new URI(Text.orEmpty(url).trim());
            if (uri.getHost() == null && uri.getAuthority() != null) {
                uri = new URI("https", null, uri.getAuthority(), uri.getPath(), uri.getQuery(), uri.getFragment());
            }
            return uri;
        } catch (Exception error) {
            return null;
        }
    }

    /** Percent-encodes a query so it can be appended to a suggestions request. */
    public static String encodeQuery(String query) {
        try {
            return URLEncoder.encode(Text.orEmpty(query), "UTF-8");
        } catch (Exception error) {
            return Text.orEmpty(query);
        }
    }
}

package org.wordpress.benchmark.domains.base;

import android.app.Activity;
import android.content.Intent;

import org.json.JSONObject;

import java.util.Locale;

/**
 * Typed result contract of the domain checkout.
 *
 * <p>The checkout screen returns the registered domain and the owner email; a user cancellation
 * travels through the same contract with the cancelled flag set. A result that does not carry a
 * usable domain and email is rejected by {@link #fromJson(JSONObject)} so that it can never be
 * reported as a completed registration.</p>
 */
public final class DomainCheckoutResult {

    public static final String EXTRA_DOMAIN_NAME = "domainName";
    public static final String EXTRA_EMAIL = "email";
    public static final String EXTRA_CANCELED = "canceled";

    public final String domainName;
    public final String email;
    public final boolean cancelled;

    private DomainCheckoutResult(String domainName, String email, boolean cancelled) {
        this.domainName = domainName;
        this.email = email;
        this.cancelled = cancelled;
    }

    public static DomainCheckoutResult completed(String domainName, String email) {
        return new DomainCheckoutResult(domainName, email, false);
    }

    public static DomainCheckoutResult canceled(String domainName, String email) {
        return new DomainCheckoutResult(domainName, email, true);
    }

    /** Reads the result of the checkout activity, or returns {@code null} when it is not usable. */
    public static DomainCheckoutResult fromIntent(Intent data, int resultCode) {
        if (data == null) {
            return null;
        }
        JSONObject payload = new JSONObject();
        String domain = data.getStringExtra(EXTRA_DOMAIN_NAME);
        if (Text.isBlank(domain)) {
            domain = data.getStringExtra("domain_name");
        }
        String email = data.getStringExtra(EXTRA_EMAIL);
        boolean cancelled = data.getBooleanExtra(EXTRA_CANCELED, resultCode == Activity.RESULT_CANCELED);
        Text.put(payload, EXTRA_DOMAIN_NAME, domain);
        Text.put(payload, EXTRA_EMAIL, email);
        payload.put(EXTRA_CANCELED, cancelled);
        return fromJson(payload);
    }

    /** Parses a checkout result payload, returning {@code null} when the result is missing/invalid. */
    public static DomainCheckoutResult fromJson(JSONObject json) {
        if (json == null || json.isNull(EXTRA_CANCELED) && !json.has(EXTRA_CANCELED)) {
            return null;
        }
        String domain = Text.first(json, new String[] { EXTRA_DOMAIN_NAME, "domain_name", "domain", "domainName" });
        String email = Text.first(json, new String[] { EXTRA_EMAIL, "emailAddress", "email_address" });
        boolean cancelled = Text.firstBoolean(json, new String[] {
                EXTRA_CANCELED, "cancelled", "isCanceled", "wasCanceled", "cancel" }, false);
        if (Text.isBlank(domain) || Text.isBlank(email)) {
            return null;
        }
        return new DomainCheckoutResult(domain.trim(), email.trim(), cancelled);
    }

    /** Explains why a payload could not be accepted as a checkout result. */
    public static String rejectionReason(JSONObject json) {
        if (json == null) {
            return "checkout returned no result";
        }
        String domain = Text.first(json, new String[] { EXTRA_DOMAIN_NAME, "domain_name", "domain", "domainName" });
        if (Text.isBlank(domain)) {
            return "checkout result is missing the registered domain";
        }
        String email = Text.first(json, new String[] { EXTRA_EMAIL, "emailAddress", "email_address" });
        if (Text.isBlank(email)) {
            return "checkout result is missing the owner email";
        }
        return "checkout result could not be read";
    }

    public boolean isCanceled() {
        return cancelled;
    }

    public boolean isCompleted() {
        return !cancelled;
    }

    /** True when the result reports the same domain the purchase flow started with. */
    public boolean matchesDomain(String domain) {
        return !Text.isBlank(domain) && domain.trim().toLowerCase(Locale.ROOT).equals(domainName.toLowerCase(Locale.ROOT));
    }

    public Intent toIntent() {
        Intent intent = new Intent();
        intent.putExtra(EXTRA_DOMAIN_NAME, domainName);
        intent.putExtra(EXTRA_EMAIL, email);
        intent.putExtra(EXTRA_CANCELED, cancelled);
        return intent;
    }

    public JSONObject toJson() {
        JSONObject json = new JSONObject();
        json.put(EXTRA_DOMAIN_NAME, domainName);
        json.put(EXTRA_EMAIL, email);
        json.put(EXTRA_CANCELED, cancelled);
        json.put("isSuccess", isCompleted());
        return json;
    }

    @Override public String toString() {
        return toJson().toString();
    }
}

