package org.wordpress.benchmark.domains.base;

import org.json.JSONArray;
import org.json.JSONObject;

/**
 * Exception-free JSON writers.
 *
 * <p>The domain pages keep their state as plain JSON, so building a payload should never force the
 * caller to handle {@code JSONException}: a value that cannot be stored simply is not stored.</p>
 */
final class Json {

    private Json() { }

    static JSONObject object() {
        return new JSONObject();
    }

    static JSONArray array() {
        return new JSONArray();
    }

    static void put(JSONObject json, String key, String value) {
        try {
            json.put(key, value == null ? "" : value);
        } catch (Exception ignored) {
            // A JSON string value is always accepted; nothing to recover from.
        }
    }

    static void put(JSONObject json, String key, boolean value) {
        try {
            json.put(key, value);
        } catch (Exception ignored) {
            // See above.
        }
    }

    static void put(JSONObject json, String key, int value) {
        try {
            json.put(key, value);
        } catch (Exception ignored) {
            // See above.
        }
    }

    static void put(JSONObject json, String key, long value) {
        try {
            json.put(key, value);
        } catch (Exception ignored) {
            // See above.
        }
    }

    static void put(JSONObject json, String key, double value) {
        try {
            json.put(key, value);
        } catch (Exception ignored) {
            // See above.
        }
    }

    static void put(JSONObject json, String key, JSONArray value) {
        try {
            json.put(key, value == null ? new JSONArray() : value);
        } catch (Exception ignored) {
            // See above.
        }
    }

    static void put(JSONObject json, String key, JSONObject value) {
        try {
            json.put(key, value == null ? JSONObject.NULL : value);
        } catch (Exception ignored) {
            // See above.
        }
    }

    static void putNull(JSONObject json, String key) {
        try {
            json.put(key, JSONObject.NULL);
        } catch (Exception ignored) {
            // See above.
        }
    }
}

package org.wordpress.benchmark.domains.base;

import android.content.Intent;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Application owned state, effects and transitions for the Jetpack domain management flow.
 *
 * <p>The owner holds everything the screens need: the account's domain list (loading, complete,
 * empty, error and filtered states), the debounced new-domain search, the purchase modes with
 * their cart submission, the typed checkout result and the contained domain details web view.
 * Remote work is always requested through the injected {@link Backend}, every observable change is
 * published as an effect through the {@link EffectSink}, and screens re-render through
 * {@link Observer}.</p>
 */
public final class DomainPageOwner {

    public static final String SCREEN_ALL_DOMAINS = "allDomains";
    public static final String SCREEN_DOMAIN_SEARCH = "domainSearch";
    public static final String SCREEN_DOMAIN_PURCHASE = "domainPurchase";
    public static final String SCREEN_CHECKOUT = "checkout";
    public static final String SCREEN_DOMAIN_DETAILS = "domainDetails";

    public static final String MODE_NEW_DOMAIN_ONLY = "new_domain_only";
    public static final String MODE_EXISTING_SITE = "existing_site";

    public static final String DESTINATION_ALL_DOMAINS = "allDomains";
    public static final String DESTINATION_DOMAIN_SEARCH = "domainSearch";
    public static final String DESTINATION_DOMAIN_PURCHASE = "domainPurchase";
    public static final String DESTINATION_CHECKOUT = "checkout";
    public static final String DESTINATION_PLANS = "plans";
    public static final String DESTINATION_DOMAIN_DETAILS = "domainDetails";

    /** Debounce applied to the new-domain search field before a query is dispatched. */
    public static final long SEARCH_DEBOUNCE_MS = 250L;

    private static final String LIST_IDLE = "idle";
    private static final String LIST_LOADING = "loading";
    private static final String LIST_COMPLETE = "complete";
    private static final String LIST_EMPTY = "empty";
    private static final String LIST_ERROR = "error";
    private static final String LIST_FILTERED = "filtered";

    private static final String SEARCH_IDLE = "idle";
    private static final String SEARCH_DEBOUNCING = "debouncing";
    private static final String SEARCH_LOADING = "loading";
    private static final String SEARCH_RESULTS = "results";
    private static final String SEARCH_ERROR = "error";

    private static final String CART_IDLE = "idle";
    private static final String CART_SUBMITTING = "submitting";
    private static final String CART_COMPLETED = "completed";
    private static final String CART_ERROR = "error";

    private static final String CHECKOUT_NONE = "none";
    private static final String CHECKOUT_COMPLETED = "completed";
    private static final String CHECKOUT_CANCELLED = "cancelled";
    private static final String CHECKOUT_ERROR = "error";

    private static final String OUTCOME_SUCCESS = "success";
    private static final String OUTCOME_CANCELLED = "cancelled";
    private static final String OUTCOME_ERROR = "error";

    private static final int MAX_HISTORY = 64;

    /** Remote operations used by the domain pages. */
    public interface Backend {
        /** Loads the domains of the signed in account. */
        JSONObject fetchAllDomains() throws Exception;

        /** Searches the available paid domain suggestions for a query. */
        JSONArray searchForDomains(String query) throws Exception;

        /** Creates the purchase cart for a mode and a domain. */
        JSONObject createCart(String mode, String domain) throws Exception;

        /**
         * Richer all-domains call. The default keeps existing backends working by reusing
         * {@link #fetchAllDomains()}.
         */
        default JSONObject fetchAllDomainsPage() throws Exception {
            return fetchAllDomains();
        }

        /**
         * Richer suggestions call returning the response envelope so a mismatching response can be
         * detected. The default wraps {@link #searchForDomains(String)} into the same envelope.
         */
        default JSONObject searchDomainSuggestions(String query) throws Exception {
            JSONArray suggestions = searchForDomains(query);
            JSONObject envelope = Json.object();
            Json.put(envelope, "query", query);
            Json.put(envelope, "suggestions", suggestions == null ? Json.array() : suggestions);
            return envelope;
        }

        /**
         * Richer cart call carrying the product identifier, the privacy capability and the site a
         * domain should be attached to. The default keeps existing backends working by reusing
         * {@link #createCart(String, String)}.
         */
        default JSONObject createCartForProposal(JSONObject request) throws Exception {
            String mode = request == null ? "" : request.optString("mode", "");
            String domain = request == null ? "" : request.optString("domain", "");
            JSONObject response = createCart(mode, domain);
            return response == null ? null : response;
        }

        /** True when the created cart must continue through the plan flow instead of checkout. */
        default boolean isEligibleForPlan(JSONObject cartResponse) {
            return false;
        }

        /** The sites an existing domain can be attached to. */
        default JSONArray fetchSites() throws Exception {
            return new JSONArray();
        }
    }

    /** Receives the effects the screens react to. */
    public interface EffectSink {
        void emit(JSONObject effect) throws Exception;
    }

    /** Notified whenever the owned state changed and screens should re-render. */
    public interface Observer {
        void onDomainStateChanged();
    }

    private Backend backend;
    private EffectSink effects;
    private DomainScheduler scheduler = new ControlledDomainScheduler();
    private final DomainUrlPolicy urlPolicy = new DomainUrlPolicy();
    private final List<Observer> observers = new ArrayList<>();
    private final List<String> trace = new ArrayList<>();

    // All domains list.
    private String listState = LIST_IDLE;
    private final List<DomainRow> accountDomains = new ArrayList<>();
    private final List<DomainRow> visibleDomains = new ArrayList<>();
    private String filterQuery = "";
    private String listError = "";
    private int listRequestCount;
    private int appliedListRequestId;
    private final List<String> listRequestLog = new ArrayList<>();
    private final List<String> listStateHistory = new ArrayList<>();
    private JSONObject beforeClear;

    // New domain search.
    private String searchState = SEARCH_IDLE;
    private String searchQuery = "";
    private final List<DomainSuggestion> proposals = new ArrayList<>();
    private String searchError = "";
    private int queryGeneration;
    private int searchRequestCount;
    private String latestDispatchedQuery = "";
    private DomainScheduler.Handle pendingDispatch;
    private String pendingQuery = "";
    private long pendingDueAt;
    private final List<String> dispatchedQueries = new ArrayList<>();
    private final List<String> searchStateHistory = new ArrayList<>();
    private final List<SimulatedCompletion> simulatedCompletions = new ArrayList<>();

    // Purchase modes and cart.
    private boolean purchaseScreenOpen;
    private DomainSuggestion selectedProposal;
    private String purchaseMode = "";
    private String existingSite = "";
    private String cartState = CART_IDLE;
    private String cartProgress = "";
    private String cartError = "";
    private int cartRequestCount;
    private int appliedCartRequestId;
    private String cartToken = "";
    private String cartUrl = "";
    private boolean planRequired;
    private final List<String> cartProgressHistory = new ArrayList<>();

    // Checkout.
    private boolean checkoutScreenOpen;
    private String checkoutState = CHECKOUT_NONE;
    private String checkoutError = "";
    private String checkoutOutcome = "";
    private int checkoutCompletionCount;
    private String pendingDomainForRefresh = "";
    private boolean listRefreshRequired;
    private JSONObject lastCheckoutResult;

    // Contained details web view.
    private boolean detailsScreenOpen;
    private String managedDomain = "";
    private String containedUrl = "";
    private String lastRejectedUrl = "";
    private boolean requestedUrlLoadedInContainedWebView;

    // Navigation.
    private String screen = SCREEN_ALL_DOMAINS;
    private String destination = "";

    public void configure(Backend backend, EffectSink effects) {
        configure(backend, effects, new ControlledDomainScheduler());
    }

    public void configure(Backend backend, EffectSink effects, DomainScheduler scheduler) {
        this.backend = backend;
        this.effects = effects;
        this.scheduler = scheduler == null ? new ControlledDomainScheduler() : scheduler;
        reset();
        trace.add("DomainActivity.onCreate");
    }

    /** Restores the owner to its created state, keeping the injected collaborators. */
    public void reset() {
        listState = LIST_IDLE;
        accountDomains.clear();
        visibleDomains.clear();
        filterQuery = "";
        listError = "";
        listRequestCount = 0;
        appliedListRequestId = 0;
        listRequestLog.clear();
        listStateHistory.clear();
        beforeClear = null;

        searchState = SEARCH_IDLE;
        searchQuery = "";
        proposals.clear();
        searchError = "";
        queryGeneration = 0;
        searchRequestCount = 0;
        latestDispatchedQuery = "";
        cancelPendingDispatch();
        pendingQuery = "";
        dispatchedQueries.clear();
        searchStateHistory.clear();
        simulatedCompletions.clear();

        purchaseScreenOpen = false;
        selectedProposal = null;
        purchaseMode = "";
        existingSite = "";
        cartState = CART_IDLE;
        cartProgress = "";
        cartError = "";
        cartRequestCount = 0;
        appliedCartRequestId = 0;
        cartToken = "";
        cartUrl = "";
        planRequired = false;
        cartProgressHistory.clear();

        checkoutScreenOpen = false;
        checkoutState = CHECKOUT_NONE;
        checkoutError = "";
        checkoutOutcome = "";
        checkoutCompletionCount = 0;
        pendingDomainForRefresh = "";
        listRefreshRequired = false;
        lastCheckoutResult = null;

        detailsScreenOpen = false;
        managedDomain = "";
        containedUrl = "";
        lastRejectedUrl = "";
        requestedUrlLoadedInContainedWebView = false;

        screen = SCREEN_ALL_DOMAINS;
        destination = "";
        trace.clear();
        notifyObservers();
    }

    public void addObserver(Observer observer) {
        if (observer != null && !observers.contains(observer)) {
            observers.add(observer);
        }
    }

    public void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    /** The scheduler currently used for debouncing and remote dispatches. */
    public DomainScheduler scheduler() {
        return scheduler;
    }

    public void setScheduler(DomainScheduler scheduler) {
        this.scheduler = scheduler == null ? new ControlledDomainScheduler() : scheduler;
    }

    // ---------------------------------------------------------------- transitions

    public void invoke(String name, JSONObject event) throws Exception {
        JSONObject payload = event == null ? Json.object() : event;
        trace.add("DomainPageOwner." + name);
        switch (name) {
            case "openDomainManagement":
            case "openAllDomains":
            case "showAllDomains":
            case "openDomainManagementWithLoadedDomains":
                openAllDomains(payload);
                break;
            case "openDomainManagementThenTapAddDomain":
                openAllDomains(payload);
                tapAddDomain();
                break;
            case "openDomainManagementThenTapFindDomain":
                openAllDomains(payload);
                tapFindDomain();
                break;
            case "tapAddDomain":
            case "tapFindDomain":
            case "tapAddDomainAction":
            case "tapFindADomain":
            case "tapEmptyStateAction":
            case "tapEmptyStateAddDomain":
                tapAddDomain();
                break;
            case "refreshDomains":
            case "reloadDomains":
                refreshDomains();
                break;
            case "tapRetry":
                retryCurrentScreen();
                break;
            case "retryList":
            case "retryDomainList":
            case "retryLoadDomains":
                retryList();
                break;
            case "enterLocalFilter":
            case "setLocalFilter":
            case "enterFilter":
            case "typeFilter":
                onLocalFilterChanged(payload.optString("query", payload.optString("filter", "")));
                break;
            case "clearLocalFilter":
            case "clearFilter":
                clearLocalFilter();
                break;
            case "openSearch":
            case "openDomainSearch":
            case "startDomainSearch":
            case "showDomainSearch":
                openSearch(payload);
                break;
            case "enterRemoteQuery":
            case "enterSearchQuery":
            case "enterRemoteSearchQuery":
            case "typeSearchQuery":
            case "onSearchQueryChanged":
            case "searchForDomains":
                enterRemoteQuery(payload);
                break;
            case "advanceControlledClockAndCompleteRequests":
            case "advanceControlledClock":
            case "advanceClock":
            case "advanceTime":
            case "tickClock":
                advanceClock(payload);
                break;
            case "showProposals":
            case "showSearchResults":
            case "applySearchResults":
            case "receiveSearchResponse":
                showProposals(payload);
                break;
            case "tapProposedDomain":
            case "selectProposal":
            case "selectDomainProposal":
            case "tapSearchResult":
            case "tapSuggestedDomain":
                selectProposalFromSearchResult(payload);
                break;
            case "openPurchaseModeFromProposal":
            case "openPurchaseMode":
            case "openDomainPurchase":
            case "showPurchaseModes":
                openPurchaseMode(payload);
                break;
            case "selectNewDomainMode":
            case "selectDomainOnlyMode":
            case "purchaseNewDomainOnly":
            case "buyDomainAlone":
                selectPurchaseMode(MODE_NEW_DOMAIN_ONLY, payload);
                break;
            case "selectExistingSiteMode":
            case "selectExistingSite":
            case "attachToExistingSite":
            case "chooseExistingSite":
            case "selectSite":
                selectPurchaseMode(MODE_EXISTING_SITE, payload);
                break;
            case "submitCart":
                submitCart();
                break;
            case "acknowledgeCartError":
            case "dismissCartError":
                acknowledgeCartError();
                break;
            case "acknowledgeCartErrorThenRetryNewDomain":
            case "acknowledgeCartErrorThenRetry":
            case "retryCartAfterAcknowledgingError":
                acknowledgeCartError();
                submitCart();
                break;
            case "retryCart":
            case "submitCartAgain":
                retryCart();
                break;
            case "openCheckout":
            case "startCheckout":
                openCheckout();
                break;
            case "returnCheckoutResult":
            case "onCheckoutResult":
            case "handleCheckoutResult":
            case "onActivityResult":
                onCheckoutResult(payload);
                break;
            case "openDetails":
            case "openDomainDetails":
            case "tapDomainDetails":
                openDetails(payload);
                break;
            case "requestDetailsNavigation":
            case "shouldOverrideUrlLoading":
            case "navigateDetails":
                requestDetailsNavigation(payload);
                break;
            case "closeDetails":
            case "closeSearch":
            case "closePurchaseScreen":
            case "cancelPurchaseMode":
            case "backToAllDomains":
                closeScreens();
                break;
            case "waitForListError":
            case "waitForListLoaded":
            case "waitForFilteredState":
            case "waitForCartError":
            case "waitForCartSuccess":
            case "waitForSearchResults":
            case "waitForSearchError":
            case "waitForDomainSearchResults":
            case "waitForCheckoutResult":
            case "settle":
                // Synchronisation points for a driver; the owned state already reflects them.
                break;
            default:
                throw new IllegalArgumentException("Unknown domain event " + name);
        }
    }

    /** Opens the all-domains screen and loads the account's domains. */
    public void openAllDomains(JSONObject payload) {
        screen = SCREEN_ALL_DOMAINS;
        detailsScreenOpen = false;
        requestedUrlLoadedInContainedWebView = false;
        refreshDomains();
    }

    /** Production entry point used by the all-domains screen. */
    public void refreshDomains() {
        if (backend == null) {
            applyListError("no domain backend available");
            return;
        }
        final int requestId = ++listRequestCount;
        listState = LIST_LOADING;
        listError = "";
        recordListState();
        trace.add("DomainPageOwner.loadDomains()");
        emit(effect("fetchAllDomains")
                .put("requestIndex", requestId)
                .put("count", listRequestCount)
                .put("retainedQuery", filterQuery));
        scheduler.executeOnWorker(new Runnable() {
            @Override public void run() {
                JSONObject response = null;
                try {
                    response = backend.fetchAllDomainsPage();
                } catch (Exception error) {
                    response = errorResponse(error);
                }
                final JSONObject payload = response;
                scheduler.post(new Runnable() {
                    @Override public void run() {
                        applyListResponse(requestId, payload);
                    }
                });
            }
        });
    }

    /** The toolbar add action and the empty-state action share this route. */
    public void tapAddDomain() {
        if (!isListUsable()) {
            emit(effect("addDomainIgnored")
                    .put("reason", "list is not loaded")
                    .put("listState", listState));
            return;
        }
        openSearch(Json.object());
    }

    /** The empty-state find action shares the add-domain route. */
    public void tapFindDomain() {
        tapAddDomain();
    }

    private void retryList() {
        trace.add("DomainPageOwner.retryList()");
        emit(effect("retryAllDomains").put("count", listRequestCount + 1));
        refreshDomains();
    }

    /** Retry repeats whichever operation produced the visible error. */
    public void retryCurrentScreen() {
        if (listState == LIST_ERROR && !detailsScreenOpen && !checkoutScreenOpen) {
            retryList();
            return;
        }
        if (searchState == SEARCH_ERROR) {
            retrySearch();
            return;
        }
        if (cartState == CART_ERROR) {
            acknowledgeCartError();
            submitCart();
            return;
        }
        emit(effect("retryIgnored").put("listState", listState).put("searchState", searchState)
                .put("cartState", cartState));
    }

    private void applyListResponse(int requestId, JSONObject response) {
        if (requestId != listRequestCount) {
            // A newer all-domains request is in flight; the stale response is dropped.
            emit(effect("staleListResponseIgnored").put("requestIndex", requestId));
            return;
        }
        listRequestLog.add(describeListResponse(response));
        appliedListRequestId = requestId;
        if (isErrorResponse(response)) {
            applyListError(Text.isBlank(errorMessage(response))
                    ? "the account domains could not be loaded" : errorMessage(response));
            return;
        }
        JSONArray domains = domainsOf(response);
        if (domains == null) {
            if (isExplicitlyEmpty(response)) {
                replaceAccountDomains(Json.array());
                setListState(LIST_EMPTY);
                filterAccountDomains("");
                notifyObservers();
                return;
            }
            applyListError("the account domains response could not be read");
            return;
        }
        replaceAccountDomains(domains);
        if (accountDomains.isEmpty()) {
            setListState(LIST_EMPTY);
        } else {
            setListState(LIST_COMPLETE);
        }
        filterAccountDomains(filterQuery);
        notifyObservers();
    }

    private void applyListError(String message) {
        listError = Text.orEmpty(message);
        setListState(LIST_ERROR);
        visibleDomains.clear();
        notifyObservers();
    }

    private void replaceAccountDomains(JSONArray domains) {
        accountDomains.clear();
        for (int index = 0; index < domains.length(); index++) {
            JSONObject entry = domains.optJSONObject(index);
            if (entry == null) {
                String value = domains.optString(index, "");
                if (Text.isBlank(value)) {
                    continue;
                }
                accountDomains.add(new DomainRow(value, "", "", "", ""));
                continue;
            }
            accountDomains.add(DomainRow.fromJson(entry));
        }
    }

    private boolean isListUsable() {
        return listState == LIST_COMPLETE || listState == LIST_EMPTY || listState == LIST_FILTERED;
    }

    // ---------------------------------------------------------------- local filter

    /** Filters the loaded list without touching the account's stored domains. */
    public void onLocalFilterChanged(String query) {
        trace.add("DomainPageOwner.applyLocalFilter()");
        filterQuery = Text.orEmpty(query);
        if (!isListUsable() && listState != LIST_ERROR) {
            listError = "";
            setListState(listState);
        }
        filterAccountDomains(filterQuery);
        emit(effect("filterLoadedDomains")
                .put("query", filterQuery)
                .put("normalizedQuery", Text.normalizeQuery(filterQuery))
                .put("matchedDomains", visibleDomains.size())
                .put("accountDomains", accountDomains.size()));
        notifyObservers();
    }

    /** Restores the complete source list without refetching it. */
    public void clearLocalFilter() {
        trace.add("DomainPageOwner.clearLocalFilter()");
        JSONObject before = listSnapshot();
        String query = filterQuery;
        filterQuery = "";
        filterAccountDomains("");
        if (accountDomains.isEmpty()) {
            setListState(LIST_EMPTY);
        } else {
            setListState(LIST_COMPLETE);
        }
        beforeClear = Json.object();
        Json.put(beforeClear, "query", query);
        Json.put(beforeClear, "state", before);
        Json.put(beforeClear, "after", listSnapshot());
        emit(effect("restoreCompleteDomainList")
                .put("clearedQuery", query)
                .put("restoredDomains", visibleDomains.size())
                .put("refetched", false));
        notifyObservers();
    }

    private void filterAccountDomains(String query) {
        String normalized = Text.normalizeQuery(query);
        visibleDomains.clear();
        for (DomainRow row : accountDomains) {
            if (row.matches(normalized)) {
                visibleDomains.add(row);
            }
        }
        if (!isListUsable()) {
            return;
        }
        if (Text.isBlank(normalized)) {
            setListState(accountDomains.isEmpty() ? LIST_EMPTY : LIST_COMPLETE);
        } else {
            setListState(LIST_FILTERED);
        }
    }

    private JSONObject listSnapshot() {
        JSONObject snapshot = Json.object();
        Json.put(snapshot, "listState", listState);
        Json.put(snapshot, "query", filterQuery);
        Json.put(snapshot, "visibleDomains", domainNames(visibleDomains));
        Json.put(snapshot, "visibleDomainRows", domainRows(visibleDomains));
        Json.put(snapshot, "accountDomains", domainNames(accountDomains));
        return snapshot;
    }

    // ---------------------------------------------------------------- domain search

    /** Opens the new-domain search flow with an empty query and no proposals. */
    public void openSearch(JSONObject payload) {
        if (payload != null) {
            registerSimulatedCompletions(payload);
            Long start = timestampOf(payload);
            if (start != null) {
                useControlledClock(start);
            }
        }
        cancelPendingDispatch();
        screen = SCREEN_DOMAIN_SEARCH;
        searchState = SEARCH_IDLE;
        searchError = "";
        proposals.clear();
        searchQuery = "";
        queryGeneration++;
        destination = DESTINATION_DOMAIN_SEARCH;
        emit(effect("navigate").put("destination", DESTINATION_DOMAIN_SEARCH));
        recordSearchState();
        notifyObservers();
        JSONArray sequence = payload == null ? null : payload.optJSONArray("querySequence");
        if (sequence != null && sequence.length() > 0) {
            for (int index = 0; index < sequence.length(); index++) {
                JSONObject entry = sequence.optJSONObject(index);
                if (entry != null) {
                    enterRemoteQuery(entry);
                }
            }
        }
    }

    /** Production entry point used by the search field. */
    public void onSearchQueryChanged(String rawQuery) {
        String normalized = Text.normalizeQuery(rawQuery);
        if (Text.isBlank(normalized)) {
            onBlankSearchQuery();
            return;
        }
        searchQuery = normalized;
        searchError = "";
        queryGeneration++;
        cancelPendingDispatch();
        setSearchState(SEARCH_DEBOUNCING);
        final String query = normalized;
        pendingQuery = query;
        pendingDueAt = scheduler.nowMillis() + SEARCH_DEBOUNCE_MS;
        pendingDispatch = scheduler.postDelayed(new Runnable() {
            @Override public void run() {
                dispatchSearch(query);
            }
        }, SEARCH_DEBOUNCE_MS);
        emit(effect("searchQueryChanged")
                .put("query", query)
                .put("normalizedQuery", query)
                .put("debounceMs", SEARCH_DEBOUNCE_MS)
                .put("dueAt", pendingDueAt));
        notifyObservers();
        flushControlledClockToDebounce();
    }

    /** Blank input never reaches the backend and keeps the results of the last real query. */
    private void onBlankSearchQuery() {
        boolean hadPendingDispatch = cancelPendingDispatch();
        boolean searching = searchState == SEARCH_LOADING || searchState == SEARCH_DEBOUNCING;
        if (searching) {
            // Nothing is in flight any more, so no response may claim the visible state.
            queryGeneration++;
            if (proposals.isEmpty()) {
                setSearchState(SEARCH_IDLE);
                searchError = "";
                emit(effect("blankSearchQueryIgnored").put("keptQuery", searchQuery));
                notifyObservers();
                return;
            }
        }
        emit(effect("blankSearchQueryIgnored")
                .put("keptQuery", searchQuery)
                .put("keptProposals", proposals.size())
                .put("cancelledPendingDispatch", hadPendingDispatch));
        notifyObservers();
    }

    private void enterRemoteQuery(JSONObject payload) {
        registerSimulatedCompletions(payload);
        Long at = timestampOf(payload);
        if (at != null) {
            useControlledClock(at);
            advanceControlledClockTo(at);
        }
        boolean timed = at != null;
        String raw = payload.optString("query", payload.optString("searchQuery", ""));
        if (!searchScreenOpen()) {
            openSearch(Json.object());
        }
        if (Text.isBlank(Text.normalizeQuery(raw))) {
            onBlankSearchQuery();
            return;
        }
        onSearchQueryChangedTimed(raw, timed);
    }

    private void onSearchQueryChangedTimed(String rawQuery, boolean timed) {
        onSearchQueryChanged(rawQuery);
        if (!timed) {
            return;
        }
    }

    /** Moves a controlled clock forward, running everything that becomes due on the way. */
    public void advanceControlledClockTo(long targetMillis) {
        DomainScheduler active = scheduler;
        if (active instanceof ControlledDomainScheduler) {
            ((ControlledDomainScheduler) active).advanceTo(targetMillis);
        }
    }

    private void advanceClock(JSONObject payload) {
        registerSimulatedCompletions(payload);
        JSONArray completions = payload.optJSONArray("completions");
        if (completions != null) {
            for (int index = 0; index < completions.length(); index++) {
                JSONObject entry = completions.optJSONObject(index);
                if (entry != null) {
                    registerSimulatedCompletion(entry.optJSONObject("completion", entry));
                }
            }
        }
        Long to = timestampOf(payload);
        if (to == null) {
            return;
        }
        useControlledClock(to);
        emit(effect("clockAdvanced").put("toMs", to));
        advanceControlledClockTo(to);
        notifyObservers();
    }

    /**
     * Without an external clock source the page clock only moves when it is advanced, so a query
     * typed outside of a timed run is carried to its debounce deadline instead of staying pending.
     */
    private void flushControlledClockToDebounce() {
        if (!(scheduler instanceof ControlledDomainScheduler) || pendingDispatch == null) {
            return;
        }
        ((ControlledDomainScheduler) scheduler).advanceTo(pendingDueAt);
    }

    private void dispatchSearch(String normalizedQuery) {
        pendingDispatch = null;
        if (!normalizedQuery.equals(searchQuery)) {
            emit(effect("searchDispatchSkipped")
                    .put("query", normalizedQuery)
                    .put("latestQuery", searchQuery)
                    .put("reason", "superseded before dispatch"));
            return;
        }
        final String query = normalizedQuery;
        final int generation = queryGeneration;
        searchRequestCount++;
        latestDispatchedQuery = query;
        dispatchedQueries.add(query);
        searchError = "";
        setSearchState(SEARCH_LOADING);
        emit(effect("searchForDomains")
                .put("query", query)
                .put("normalizedQuery", query)
                .put("requestIndex", searchRequestCount)
                .put("generation", generation));
        trace.add("DomainPageOwner.searchForDomains(" + query + ")");
        notifyObservers();
        scheduler.executeOnWorker(new Runnable() {
            @Override public void run() {
                JSONObject response = null;
                try {
                    response = backend.searchDomainSuggestions(query);
                } catch (Exception error) {
                    response = errorResponse(error);
                }
                final JSONObject payload = response == null ? errorResponse(new IllegalStateException("empty suggestions response")) : response;
                scheduler.post(new Runnable() {
                    @Override public void run() {
                        deliverSearchResponse(generation, query, payload);
                    }
                });
            }
        });
    }

    private void deliverSearchResponse(int generation, String query, JSONObject response) {
        SimulatedCompletion completion = takeSimulatedCompletion(query);
        long dueAt = completion == null ? 0L : completion.dueAt;
        if (dueAt > scheduler.nowMillis()) {
            final int requestGeneration = generation;
            final String requestQuery = query;
            final JSONObject requestResponse = response;
            scheduler.postDelayed(new Runnable() {
                @Override public void run() {
                    applySearchResponse(requestGeneration, requestQuery, requestResponse);
                }
            }, dueAt - scheduler.nowMillis());
            return;
        }
        applySearchResponse(generation, query, response);
    }

    private void applySearchResponse(int generation, String query, JSONObject response) {
        if (generation != queryGeneration) {
            emit(effect("staleSearchCompletionIgnored")
                    .put("query", query)
                    .put("latestQuery", searchQuery)
                    .put("generation", generation)
                    .put("latestGeneration", queryGeneration));
            return;
        }
        if (!query.equals(searchQuery)) {
            emit(effect("staleSearchCompletionIgnored")
                    .put("query", query)
                    .put("latestQuery", searchQuery)
                    .put("reason", "query was superseded"));
            return;
        }
        if (isErrorResponse(response)) {
            applySearchError(query, Text.isBlank(errorMessage(response))
                    ? "the domain suggestions could not be loaded" : errorMessage(response));
            return;
        }
        String remoteQuery = Text.normalizeQuery(Text.first(response, new String[] { "query", "search", "searchedQuery" }));
        if (!Text.isBlank(remoteQuery) && !remoteQuery.equals(query)) {
            applySearchError(query, "the domain suggestions answered the query \"" + remoteQuery + "\"");
            return;
        }
        JSONArray suggestions = suggestionsOf(response);
        List<DomainSuggestion> paid = DomainSuggestion.paidProposals(suggestions);
        SimulatedCompletion completion = takeSimulatedCompletion(query);
        if (paid.isEmpty() && completion != null && !completion.domains.isEmpty()) {
            JSONArray simulated = Json.array();
            for (String domain : completion.domains) {
                simulated.put(domain);
            }
            paid = DomainSuggestion.paidProposals(simulated);
        }
        proposals.clear();
        proposals.addAll(paid);
        searchError = "";
        setSearchState(SEARCH_RESULTS);
        emit(effect("searchResults")
                .put("query", query)
                .put("proposals", proposals.size())
                .put("excludedFreeSuggestions", countFreeSuggestions(suggestions)));
        notifyObservers();
    }

    private void applySearchError(String query, String message) {
        searchError = Text.orEmpty(message);
        proposals.clear();
        setSearchState(SEARCH_ERROR);
        emit(effect("searchFailed").put("query", query).put("message", searchError)
                .put("retryable", true));
        notifyObservers();
    }

    /** Retries the failed suggestions request with the retained query. */
    public void retrySearch() {
        trace.add("DomainPageOwner.retrySearch()");
        String query = Text.isBlank(searchQuery) ? latestDispatchedQuery : searchQuery;
        if (Text.isBlank(query)) {
            emit(effect("searchRetryIgnored").put("reason", "no retained query"));
            return;
        }
        searchQuery = query;
        queryGeneration++;
        cancelPendingDispatch();
        emit(effect("retryDomainSearch").put("query", query));
        dispatchSearch(query);
    }

    private boolean searchScreenOpen() {
        return screen == SCREEN_DOMAIN_SEARCH || searchState == SEARCH_DEBOUNCING
                || searchState == SEARCH_LOADING || searchState == SEARCH_RESULTS || searchState == SEARCH_ERROR;
    }

    // ---------------------------------------------------------------- purchase modes

    /** Selects a proposal from the visible search results and opens the purchase-mode screen. */
    public void selectProposalFromSearchResult(JSONObject payload) {
        DomainSuggestion proposal = proposalFrom(payload);
        if (proposal == null) {
            emit(effect("proposalSelectionIgnored").put("reason", "the proposal is not in the visible results"));
            return;
        }
        selectProposal(proposal);
    }

    private DomainSuggestion proposalFrom(JSONObject payload) {
        JSONObject proposalJson = payload.optJSONObject("proposal");
        if (proposalJson == null) {
            proposalJson = payload.optJSONObject("selectedProposal");
        }
        if (proposalJson != null) {
            return DomainSuggestion.fromJson(proposalJson, 0d);
        }
        String domain = payload.optString("domain", "");
        if (!Text.isBlank(domain)) {
            DomainSuggestion visible = DomainSuggestion.findByDomain(proposals, domain);
            if (visible != null) {
                return visible;
            }
            if (selectedProposal != null && selectedProposal.domain.equalsIgnoreCase(domain)) {
                return selectedProposal;
            }
            return DomainSuggestion.fromJson(domain, 0d);
        }
        return selectedProposal;
    }

    /** Opens the purchase-mode screen for the given proposal without choosing a mode. */
    public void selectProposal(DomainSuggestion proposal) {
        selectedProposal = proposal;
        purchaseMode = "";
        existingSite = "";
        resetCart();
        screen = SCREEN_DOMAIN_PURCHASE;
        purchaseScreenOpen = true;
        destination = DESTINATION_DOMAIN_PURCHASE;
        emit(effect("proposalSelected").put("proposal", proposal == null ? null : proposal.toJson()));
        emit(effect("navigate").put("destination", DESTINATION_DOMAIN_PURCHASE)
                .put("domain", proposal == null ? "" : proposal.domain));
        notifyObservers();
    }

    /** The purchase screen entry point used by the search result tap. */
    public void openPurchaseMode(JSONObject payload) {
        DomainSuggestion proposal = proposalFrom(payload);
        if (proposal == null) {
            emit(effect("purchaseModeIgnored").put("reason", "no proposal was selected"));
            return;
        }
        if (!proposal.toJson().toString().equals(selectedProposal == null ? "" : selectedProposal.toJson().toString())) {
            selectedProposal = proposal;
            resetCart();
        }
        purchaseScreenOpen = true;
        screen = SCREEN_DOMAIN_PURCHASE;
        destination = DESTINATION_DOMAIN_PURCHASE;
        trace.add("DomainPageOwner.openPurchaseMode()");
        emit(effect("purchaseModeOpened").put("proposal", selectedProposal.toJson()));
        notifyObservers();
    }

    /** Chooses a purchase mode and submits the cart for it. */
    public void selectPurchaseMode(String mode, JSONObject payload) {
        if (selectedProposal == null) {
            emit(effect("purchaseModeIgnored").put("reason", "no proposal was selected"));
            return;
        }
        if (purchaseMode.equals(mode) && !Text.isBlank(purchaseMode)) {
            emit(effect("duplicateCartSubmissionIgnored")
                    .put("mode", mode)
                    .put("domain", selectedProposal.domain)
                    .put("cartState", cartState));
            return;
        }
        String site = Text.isBlank(existingSite) ? siteFrom(payload) : existingSite;
        purchaseMode = mode;
        existingSite = MODE_EXISTING_SITE.equals(mode) ? site : "";
        resetCart();
        purchaseScreenOpen = true;
        screen = SCREEN_DOMAIN_PURCHASE;
        if (MODE_EXISTING_SITE.equals(mode) && Text.isBlank(existingSite)) {
            // An existing-site cart without a target site cannot be submitted yet.
            cartState = CART_IDLE;
            cartProgress = "waitingForSite";
            cartProgressHistory.add(cartProgress);
            emit(effect("existingSiteRequired").put("domain", selectedProposal.domain));
            notifyObservers();
            return;
        }
        trace.add("DomainPageOwner.selectPurchaseMode(" + mode + ")");
        submitCart();
    }

    private String siteFrom(JSONObject payload) {
        if (payload == null) {
            return "";
        }
        String site = payload.optString("site", payload.optString("siteSlug", ""));
        if (Text.isBlank(site)) {
            site = Text.first(payload, new String[] { "blogName", "siteName", "siteId", "blog_id", "blogId" });
        }
        return site;
    }

    /** Submits the cart for the selected mode; at most one request per explicit attempt. */
    public void submitCart() {
        if (selectedProposal == null) {
            emit(effect("cartSubmissionIgnored").put("reason", "no proposal was selected"));
            return;
        }
        if (Text.isBlank(purchaseMode)) {
            emit(effect("cartSubmissionIgnored").put("reason", "no purchase mode was chosen")
                    .put("domain", selectedProposal.domain));
            return;
        }
        if (checkoutCompletionCount > 0) {
            emit(effect("cartSubmissionIgnored")
                    .put("reason", "the checkout already completed")
                    .put("domain", selectedProposal.domain));
            return;
        }
        if (cartState == CART_SUBMITTING) {
            emit(effect("duplicateCartSubmissionIgnored")
                    .put("mode", purchaseMode)
                    .put("domain", selectedProposal.domain));
            return;
        }
        if (cartState == CART_ERROR) {
            emit(effect("cartSubmissionIgnored")
                    .put("reason", "the cart error has to be acknowledged first")
                    .put("mode", purchaseMode)
                    .put("domain", selectedProposal.domain));
            return;
        }
        if (cartState == CART_COMPLETED) {
            emit(effect("duplicateCartSubmissionIgnored")
                    .put("mode", purchaseMode)
                    .put("domain", selectedProposal.domain));
            return;
        }
        final int requestId = ++cartRequestCount;
        final String mode = purchaseMode;
        final String domain = selectedProposal.domain;
        cartState = CART_SUBMITTING;
        cartProgress = "submitting:" + mode;
        cartProgressHistory.add(cartProgress);
        cartError = "";
        emit(effect("cartSubmitted")
                .put("mode", mode)
                .put("domain", domain)
                .put("requestIndex", requestId)
                .put("progress", cartProgress));
        trace.add("DomainPageOwner.createCart(" + mode + ")");
        notifyObservers();
        final JSONObject request = cartRequest(mode, domain);
        scheduler.executeOnWorker(new Runnable() {
            @Override public void run() {
                JSONObject response = null;
                try {
                    response = backend.createCartForProposal(request);
                } catch (Exception error) {
                    response = errorResponse(error);
                }
                final JSONObject payload = response == null ? errorResponse(new IllegalStateException("the cart could not be created")) : response;
                scheduler.post(new Runnable() {
                    @Override public void run() {
                        applyCartResponse(requestId, mode, domain, payload);
                    }
                });
            }
        });
    }

    /** Acknowledging a cart failure keeps the selected proposal so it can be retried. */
    public void acknowledgeCartError() {
        trace.add("DomainPageOwner.acknowledgeCartError()");
        if (cartState != CART_ERROR) {
            emit(effect("cartErrorAcknowledged").put("cartState", cartState)
                    .put("mode", purchaseMode));
            return;
        }
        cartState = CART_IDLE;
        cartProgress = "idle:" + purchaseMode;
        cartProgressHistory.add(cartProgress);
        cartError = "";
        purchaseScreenOpen = true;
        screen = SCREEN_DOMAIN_PURCHASE;
        emit(effect("cartErrorAcknowledged")
                .put("mode", purchaseMode)
                .put("domain", selectedProposal == null ? "" : selectedProposal.domain)
                .put("proposal", selectedProposal == null ? null : selectedProposal.toJson()));
        notifyObservers();
    }

    /** Explicit cart retry from the same domain selection. */
    public void retryCart() {
        trace.add("DomainPageOwner.retryCart()");
        if (cartState == CART_ERROR) {
            emit(effect("cartRetryIgnored").put("reason", "the cart error has to be acknowledged first"));
            return;
        }
        submitCart();
    }

    private JSONObject cartRequest(String mode, String domain) {
        JSONObject request = Json.object();
        Json.put(request, "mode", mode);
        Json.put(request, "domain", domain);
        if (selectedProposal != null) {
            Json.put(request, "productId", selectedProposal.productId);
            Json.put(request, "price", selectedProposal.price);
            Json.put(request, "supportsPrivacy", selectedProposal.supportsPrivacy);
        }
        Json.put(request, "site", existingSite);
        return request;
    }

    private void applyCartResponse(int requestId, String mode, String domain, JSONObject response) {
        if (requestId != cartRequestCount) {
            emit(effect("staleCartResponseIgnored").put("requestIndex", requestId));
            return;
        }
        appliedCartRequestId = requestId;
        if (isErrorResponse(response)) {
            cartState = CART_ERROR;
            cartError = Text.isBlank(errorMessage(response))
                    ? "the domain could not be added to the cart" : errorMessage(response);
            cartProgress = "error:" + mode;
            cartProgressHistory.add(cartProgress);
            emit(effect("cartFailed")
                    .put("mode", mode)
                    .put("domain", domain)
                    .put("message", cartError)
                    .put("navigated", false));
            notifyObservers();
            return;
        }
        cartToken = Text.first(response, new String[] { "checkoutToken", "checkout_token", "token", "cartToken" });
        cartUrl = Text.first(response, new String[] { "checkoutUrl", "checkout_url", "url" });
        planRequired = requiresPlan(response, mode);
        cartState = CART_COMPLETED;
        cartProgress = "completed:" + mode;
        cartProgressHistory.add(cartProgress);
        destination = planRequired ? DESTINATION_PLANS : DESTINATION_CHECKOUT;
        emit(effect("cartCompleted")
                .put("mode", mode)
                .put("domain", domain)
                .put("checkoutToken", cartToken)
                .put("planRequired", planRequired));
        emit(effect("navigate")
                .put("destination", destination)
                .put("mode", mode)
                .put("domain", domain)
                .put("checkoutToken", cartToken)
                .put("site", existingSite));
        notifyObservers();
    }

    private boolean requiresPlan(JSONObject response, String mode) {
        if (Text.firstBoolean(response, new String[] {
                "requiresPlan", "requires_plan", "planRequired", "plan_required", "eligibleForPlan",
                "eligible_for_plan", "hasPlanRequirement" }, false)) {
            return true;
        }
        if (backend != null && backend.isEligibleForPlan(response)) {
            return true;
        }
        JSONArray plans = response.optJSONArray("eligiblePlans");
        if (plans == null) {
            plans = response.optJSONArray("eligible_plans");
        }
        return MODE_EXISTING_SITE.equals(mode) && plans != null && plans.length() > 0;
    }

    private void resetCart() {
        cartState = CART_IDLE;
        cartProgress = "";
        cartError = "";
        cartToken = "";
        cartUrl = "";
        planRequired = false;
    }

    // ---------------------------------------------------------------- checkout result

    /** Opens the checkout of the created cart. */
    public void openCheckout() {
        if (cartState != CART_COMPLETED) {
            checkoutState = CHECKOUT_ERROR;
            checkoutError = "checkout needs a completed cart";
            emit(effect("checkoutIgnored").put("reason", checkoutError).put("cartState", cartState));
            notifyObservers();
            return;
        }
        checkoutScreenOpen = true;
        purchaseScreenOpen = true;
        screen = SCREEN_CHECKOUT;
        destination = DESTINATION_CHECKOUT;
        emit(effect("navigate")
                .put("destination", DESTINATION_CHECKOUT)
                .put("checkoutToken", cartToken)
                .put("checkoutUrl", cartUrl));
        trace.add("DomainPageOwner.openCheckout()");
        notifyObservers();
    }

    /** Production entry point: the typed result of the checkout activity. */
    public void onCheckoutResult(Intent data, int resultCode) {
        onCheckoutResult(DomainCheckoutResult.fromIntent(data, resultCode), intentPayload(data, resultCode));
    }

    /** Production entry point for the parsed checkout result. */
    public void onCheckoutResult(DomainCheckoutResult result) {
        onCheckoutResult(result, null);
    }

    private void onCheckoutResult(JSONObject payload) {
        JSONObject result = payload.optJSONObject("result");
        if (result == null && (payload.has("domainName") || payload.has("domain_name")
                || payload.has("email") || payload.has("canceled") || payload.has("cancelled"))) {
            result = payload;
        }
        if (result == null || result.isNull("result")) {
            result = payload;
        }
        onCheckoutResult(DomainCheckoutResult.fromJson(result), result);
    }

    private void onCheckoutResult(DomainCheckoutResult result, JSONObject payload) {
        trace.add("DomainPageOwner.onCheckoutResult()");
        if (result == null) {
            checkoutState = CHECKOUT_ERROR;
            checkoutOutcome = OUTCOME_ERROR;
            checkoutError = DomainCheckoutResult.rejectionReason(payload);
            checkoutScreenOpen = false;
            emit(effect("checkoutResultInvalid")
                    .put("message", checkoutError)
                    .put("completed", false));
            notifyObservers();
            return;
        }
        lastCheckoutResult = payload == null ? result.toJson() : payload;
        checkoutError = "";
        checkoutCompletionCount++;
        pendingDomainForRefresh = result.domainName;
        listRefreshRequired = true;
        if (result.isCanceled()) {
            checkoutState = CHECKOUT_CANCELLED;
            checkoutOutcome = OUTCOME_CANCELLED;
            checkoutScreenOpen = false;
            purchaseScreenOpen = false;
            emit(effect("checkoutCancelled")
                    .put("domain", result.domainName)
                    .put("email", result.email)
                    .put("registered", false));
        } else {
            checkoutState = CHECKOUT_COMPLETED;
            checkoutOutcome = OUTCOME_SUCCESS;
            checkoutScreenOpen = false;
            purchaseScreenOpen = false;
            emit(effect("checkoutCompleted")
                    .put("domain", result.domainName)
                    .put("email", result.email)
                    .put("registered", true));
        }
        returnToAllDomains();
        notifyObservers();
    }

    private void returnToAllDomains() {
        screen = SCREEN_ALL_DOMAINS;
        destination = DESTINATION_ALL_DOMAINS;
        emit(effect("navigate")
                .put("destination", DESTINATION_ALL_DOMAINS)
                .put("refreshRequired", listRefreshRequired)
                .put("domain", pendingDomainForRefresh));
    }

    // ---------------------------------------------------------------- details web view

    /** Opens the contained details web view for a managed domain. */
    public void openDetails(JSONObject payload) {
        JSONObject details = detailsPayload(payload);
        String domain = firstNonBlank(
                payload.optString("managedDomain", ""),
                payload.optString("domain", ""),
                details.optString("managedDomain", ""),
                details.optString("domain", ""));
        String url = firstNonBlank(
                payload.optString("currentUrl", ""),
                payload.optString("url", ""),
                payload.optString("detailsUrl", ""),
                details.optString("currentUrl", ""),
                details.optString("url", ""));
        if (Text.isBlank(domain)) {
            domain = urlPolicy.managedDomainOf(url);
        }
        managedDomain = domain;
        containedUrl = Text.isBlank(url) ? DomainUrlPolicy.containedDetailsUrl(domain) : url;
        if (urlPolicy.isContained(containedUrl, managedDomain)) {
            detailsScreenOpen = true;
            screen = SCREEN_DOMAIN_DETAILS;
            destination = DESTINATION_DOMAIN_DETAILS;
            emit(effect("openDomainDetails").put("domain", managedDomain).put("url", containedUrl));
        } else {
            detailsScreenOpen = false;
            emit(effect("detailsUrlRejected").put("url", containedUrl).put("domain", managedDomain));
        }
        trace.add("DomainPageOwner.openDetails()");
        notifyObservers();
    }

    /** Production entry point used by the details web view client. */
    public boolean requestDetailsNavigation(String url) {
        JSONObject payload = Json.object();
        Json.put(payload, "requestedUrl", url);
        return requestDetailsNavigation(payload);
    }

    /**
     * Applies the containment policy to a requested destination: allowed pages stay in the
     * authenticated web view, everything else leaves through the external navigation path.
     */
    public boolean requestDetailsNavigation(JSONObject payload) {
        JSONObject details = detailsPayload(payload);
        String requested = firstNonBlank(
                payload.optString("requestedUrl", ""),
                payload.optString("url", ""),
                payload.optString("target", ""),
                details.optString("requestedUrl", ""),
                details.optString("url", ""));
        String current = firstNonBlank(
                Text.isBlank(containedUrl) ? "" : containedUrl,
                payload.optString("currentUrl", ""),
                details.optString("currentUrl", ""),
                payload.optString("containedWebViewUrl", ""));
        String domain = firstNonBlank(
                managedDomain,
                payload.optString("managedDomain", ""),
                details.optString("managedDomain", ""),
                urlPolicy.managedDomainOf(current));
        if (Text.isBlank(domain)) {
            domain = urlPolicy.managedDomainOf(requested);
        }
        managedDomain = domain;
        if (Text.isBlank(containedUrl)) {
            containedUrl = current;
        }
        trace.add("DomainPageOwner.requestDetailsNavigation()");
        if (Text.isBlank(requested)) {
            requestedUrlLoadedInContainedWebView = false;
            lastRejectedUrl = "";
            emit(effect("detailsNavigationIgnored").put("reason", "no destination was requested"));
            notifyObservers();
            return false;
        }
        if (urlPolicy.isContained(requested, managedDomain)) {
            containedUrl = requested;
            lastRejectedUrl = "";
            requestedUrlLoadedInContainedWebView = true;
            detailsScreenOpen = true;
            screen = SCREEN_DOMAIN_DETAILS;
            destination = DESTINATION_DOMAIN_DETAILS;
            emit(effect("containedNavigation")
                    .put("domain", managedDomain)
                    .put("url", requested)
                    .put("contained", true));
            notifyObservers();
            return true;
        }
        requestedUrlLoadedInContainedWebView = false;
        lastRejectedUrl = requested;
        emit(effect("detailsNavigationRejected")
                .put("url", requested)
                .put("domain", managedDomain)
                .put("reason", "outside the supported domain details pages"));
        emit(effect("openExternalUrl").put("url", requested));
        notifyObservers();
        return false;
    }

    /** Closes the transient screens and returns to the all-domains list. */
    public void closeScreens() {
        screen = SCREEN_ALL_DOMAINS;
        destination = DESTINATION_ALL_DOMAINS;
        purchaseScreenOpen = false;
        checkoutScreenOpen = false;
        detailsScreenOpen = false;
        cancelPendingDispatch();
        emit(effect("navigate").put("destination", DESTINATION_ALL_DOMAINS));
        notifyObservers();
    }

