        JSONObject view = Json.object();
        Json.put(view, "screen", screen);
        Json.put(view, "listState", listState);
        Json.put(view, "listStateHistory", new JSONArray(listStateHistory));
        Json.put(view, "visibleDomains", domainNames(visibleDomains));
        Json.put(view, "visibleDomainRows", domainRows(visibleDomains));
        Json.put(view, "domainCount", visibleDomains.size());
        Json.put(view, "accountDomains", domainNames(accountDomains));
        Json.put(view, "accountDomainRows", domainRows(accountDomains));
        Json.put(view, "accountDomainCount", accountDomains.size());
        Json.put(view, "allDomainsRequests", listRequestCount);
        Json.put(view, "listRequestLog", new JSONArray(listRequestLog));
        Json.put(view, "listError", listError);
        Json.put(view, "listRetryAvailable", listState == LIST_ERROR);
        Json.put(view, "query", filterQuery);
        Json.put(view, "filterQuery", filterQuery);
        Json.put(view, "filterActive", !Text.isBlank(filterQuery));
        Json.put(view, "addDomainEnabled", isListUsable());
        Json.put(view, "findDomainEnabled", isListUsable());
        Json.put(view, "searchEnabled", isListUsable());
