        Json.put(view, "pendingDomainForRefresh", pendingDomainForRefresh);
        if (beforeClear != null) {
            Json.put(view, "beforeClear", beforeClear.optJSONObject("state"));
            Json.put(view, "afterClear", beforeClear.optJSONObject("after"));
        }
        Json.put(view, "destination", destination == null ? "" : destination);

        Json.put(view, "searchState", searchState);
        Json.put(view, "searchStateHistory", new JSONArray(searchStateHistory));
        Json.put(view, "searchQuery", searchQuery);
        Json.put(view, "searchDebounceMs", SEARCH_DEBOUNCE_MS);
        Json.put(view, "searchRequestCount", searchRequestCount);
        Json.put(view, "dispatchedQueries", new JSONArray(dispatchedQueries));
        Json.put(view, "latestDispatchedQuery", latestDispatchedQuery);
        Json.put(view, "searchProposals", DomainSuggestion.toJsonArray(proposals));
        Json.put(view, "proposalCount", proposals.size());
        Json.put(view, "searchError", searchError);
        Json.put(view, "searchRetryAvailable", searchState == SEARCH_ERROR);
        Json.put(view, "searchPendingDispatch", pendingDispatch != null);
        Json.put(view, "searchOpen", screen == SCREEN_DOMAIN_SEARCH);

        Json.put(view, "purchaseScreenOpen", purchaseScreenOpen);
        Json.put(view, "purchaseMode", purchaseMode);
        Json.put(view, "existingSite", existingSite);
        Json.put(view, "cartState", cartState);
        Json.put(view, "cartProgress", cartProgress);
        Json.put(view, "cartProgressHistory", new JSONArray(cartProgressHistory));
        Json.put(view, "cartRequestCount", cartRequestCount);
        Json.put(view, "cartError", cartError);
        Json.put(view, "cartRetryAvailable", cartState == CART_ERROR);
        Json.put(view, "cartToken", cartToken);
        Json.put(view, "checkoutToken", cartToken);
        Json.put(view, "cartUrl", cartUrl);
        Json.put(view, "planRequired", planRequired);
        Json.put(view, "selectedProposal",
                selectedProposal == null ? JSONObject.NULL : selectedProposal.toJson());

        Json.put(view, "checkoutScreenOpen", checkoutScreenOpen);
        Json.put(view, "checkoutState", checkoutState);
        Json.put(view, "checkoutError", checkoutError);
        Json.put(view, "checkoutOutcome", checkoutOutcome);
        Json.put(view, "registrationOutcome", checkoutOutcome);
        Json.put(view, "checkoutCompletionCount", checkoutCompletionCount);
        Json.put(view, "checkoutResult", lastCheckoutResult == null ? JSONObject.NULL : lastCheckoutResult);

        Json.put(view, "detailsScreenOpen", detailsScreenOpen);
        Json.put(view, "managedDomain", managedDomain);
        Json.put(view, "detailsUrl", Text.isBlank(managedDomain) ? "" : DomainUrlPolicy.containedDetailsUrl(managedDomain));
        Json.put(view, "containedWebViewUrl", containedUrl == null ? "" : containedUrl);
        Json.put(view, "requestedUrlLoadedInContainedWebView", requestedUrlLoadedInContainedWebView);
        Json.put(view, "rejectedUrl", lastRejectedUrl);
        Json.put(view, "externalNavigationUrl", lastRejectedUrl);
        return view;
    }

    public JSONArray invokedMethods() {
        return new JSONArray(trace);
    }

    public String ownerId() {
        return "android-domain-activity-owner";
    }

    public String storeSource() {
        return "DomainActivity.DomainPageOwner";
    }

    /** The sites an existing domain can be attached to, for the purchase screen. */
    public JSONArray sites() {
        if (backend == null) {
            return Json.array();
        }
        try {
            JSONArray sites = backend.fetchSites();
            return sites == null ? Json.array() : sites;
        } catch (Exception error) {
            emit("sitesUnavailable", "message", String.valueOf(error.getMessage()));
            return Json.array();
        }
    }

    /** Consumes the all-domains refresh requested by a completed checkout. */
    public boolean consumeListRefreshRequired() {
        boolean required = listRefreshRequired;
        listRefreshRequired = false;
        return required;
    }

    // ---------------------------------------------------------------- internals

    private void setListState(String state) {
        listState = state;
        if (listStateHistory.isEmpty() || !state.equals(listStateHistory.get(listStateHistory.size() - 1))) {
            listStateHistory.add(state);
            trim(listStateHistory);
        }
    }

    private void setSearchState(String state) {
        searchState = state;
        if (searchStateHistory.isEmpty() || !state.equals(searchStateHistory.get(searchStateHistory.size() - 1))) {
            searchStateHistory.add(state);
            trim(searchStateHistory);
        }
    }

    private void cancelPendingDispatch() {
        if (pendingDispatch != null) {
            pendingDispatch.cancel();
            pendingDispatch = null;
            pendingQuery = "";
        }
    }

    private void useControlledClock(long startMillis) {
        if (scheduler instanceof ControlledDomainScheduler) {
            return;
        }
        DomainScheduler previous = scheduler;
        String query = pendingQuery;
        long remaining = Math.max(0L, pendingDueAt - previous.nowMillis());
        cancelPendingDispatch();
        ControlledDomainScheduler controlled = new ControlledDomainScheduler(startMillis);
        scheduler = controlled;
        if (!Text.isBlank(query)) {
            pendingQuery = query;
            pendingDueAt = startMillis + remaining;
            pendingDispatch = controlled.postDelayed(new Runnable() {
                @Override public void run() {
                    dispatchSearch(query);
                }
            }, remaining);
        }
    }

    private void emit(String name, Object... keyValues) {
        if (effects == null) {
            return;
        }
        JSONObject effect = Json.object();
        Json.put(effect, "name", name);
        for (int index = 0; index + 1 < keyValues.length; index += 2) {
            Object key = keyValues[index];
            if (!(key instanceof String)) {
                continue;
            }
            Json.put(effect, (String) key, keyValues[index + 1]);
        }
        try {
            effects.emit(effect);
        } catch (Exception error) {
            // An effect sink failure must not corrupt the owned state.
        }
    }

    private void notifyObservers() {
        for (Observer observer : new ArrayList<>(observers)) {
            try {
                observer.onDomainStateChanged();
            } catch (Exception error) {
                // A screen that failed to render does not stop the flow.
            }
        }
    }

    private static void trim(List<String> values) {
        while (values.size() > MAX_HISTORY) {
            values.remove(0);
        }
    }

    private static JSONArray domainNames(List<DomainRow> rows) {
        JSONArray names = Json.array();
        for (DomainRow row : rows) {
            names.put(row.domain);
        }
        return names;
    }

    private static JSONArray domainRows(List<DomainRow> rows) {
        JSONArray result = Json.array();
        for (DomainRow row : rows) {
            result.put(row.toJson());
        }
        return result;
    }

    private static String firstNonBlank(String... values) {
        for (String value : values) {
            if (!Text.isBlank(value)) {
                return value;
            }
        }
        return "";
    }

    private static Long timestampOf(JSONObject payload) {
        if (payload == null) {
            return null;
        }
        String[] keys = { "atMs", "at", "clockMs", "timestampMs", "toMs", "nowMs", "elapsedMs" };
        for (String key : keys) {
            if (payload.has(key) && !payload.isNull(key)) {
                long value = payload.optLong(key, Long.MIN_VALUE);
                if (value != Long.MIN_VALUE) {
                    return value;
                }
            }
        }
        return null;
    }

    private static JSONObject detailsPayload(JSONObject payload) {
        JSONObject details = payload == null ? null : payload.optJSONObject("detailsWebView");
        return details == null ? Json.object() : details;
    }

    private static boolean isErrorResponse(JSONObject response) {
        if (response == null) {
            return true;
        }
        String type = response.optString("type", "");
        if ("error".equalsIgnoreCase(type) || "failure".equalsIgnoreCase(type)) {
            return true;
        }
        if (response.has("error") && !response.isNull("error") && !Text.isBlank(response.optString("error", ""))) {
            return true;
        }
        return response.optBoolean("success", true) == false;
    }

    private static boolean isExplicitlyEmpty(JSONObject response) {
        return "empty".equalsIgnoreCase(response.optString("type", ""));
    }

    private static String errorMessage(JSONObject response) {
        if (response == null) {
            return "";
        }
        return firstNonBlank(
                response.optString("error", ""),
                response.optString("message", ""),
                response.optString("errorMessage", ""),
                response.optString("code", ""));
    }

    private static JSONObject errorResponse(Exception error) {
        JSONObject response = Json.object();
        Json.put(response, "type", "error");
        String message = error == null ? "" : String.valueOf(error.getMessage());
        Json.put(response, "error", Text.isBlank(message) ? "the request failed" : message);
        return response;
    }

    private static JSONArray domainsOf(JSONObject response) {
        if (response == null) {
            return null;
        }
        JSONArray domains = response.optJSONArray("domains");
        if (domains == null) {
            domains = response.optJSONArray("accountDomains");
        }
        if (domains == null) {
            domains = response.optJSONArray("siteDomains");
        }
        return domains;
    }

    private static JSONArray suggestionsOf(JSONObject response) {
        if (response == null) {
            return Json.array();
        }
        String[] keys = { "suggestions", "results", "domains", "proposals", "items" };
        for (String key : keys) {
            JSONArray array = response.optJSONArray(key);
            if (array != null) {
                return array;
            }
        }
        return Json.array();
    }

    private static int countFreeSuggestions(JSONArray suggestions) {
        if (suggestions == null) {
            return 0;
        }
        int free = 0;
        for (int index = 0; index < suggestions.length(); index++) {
            Object entry = suggestions.opt(index);
            if (entry instanceof JSONObject && DomainSuggestion.fromJson(entry, 0d).free) {
                free++;
            }
        }
        return free;
    }

    private static String describeListResponse(JSONObject response) {
        if (isErrorResponse(response)) {
            return "error";
        }
        if (isExplicitlyEmpty(response)) {
            return "empty";
        }
        JSONArray domains = domainsOf(response);
        if (domains == null) {
            return "unreadable";
        }
        return "success:" + domains.length();
    }

    private void registerSimulatedCompletions(JSONObject payload) {
        if (payload == null) {
            return;
        }
        registerSimulatedCompletion(payload.optJSONObject("completion"));
        JSONArray sequence = payload.optJSONArray("querySequence");
        if (sequence != null) {
            for (int index = 0; index < sequence.length(); index++) {
                JSONObject entry = sequence.optJSONObject(index);
                if (entry != null) {
                    registerSimulatedCompletion(entry.optJSONObject("completion"));
                }
            }
        }
    }

    private void registerSimulatedCompletion(JSONObject completion) {
        if (completion == null) {
            return;
        }
        String query = Text.normalizeQuery(Text.first(completion, new String[] { "query", "searchQuery" }));
        if (Text.isBlank(query)) {
            return;
        }
        SimulatedCompletion simulated = new SimulatedCompletion();
        simulated.query = query;
        simulated.dueAt = Text.firstLong(completion, new String[] { "atMs", "at", "dueAtMs", "responseAtMs" }, -1L);
        JSONArray domains = completion.optJSONArray("domains");
        if (domains == null) {
            domains = completion.optJSONArray("suggestions");
        }
        if (domains != null) {
            for (int index = 0; index < domains.length(); index++) {
                Object entry = domains.opt(index);
                if (entry == null || entry == JSONObject.NULL) {
                    continue;
                }
                if (entry instanceof JSONObject) {
                    simulated.domains.add(DomainSuggestion.fromJson(entry, 0d).domain);
                } else {
                    simulated.domains.add(String.valueOf(entry));
                }
            }
        }
        if (simulated.dueAt < 0L && !simulated.domains.isEmpty()) {
            simulated.dueAt = scheduler.nowMillis();
        }
        for (SimulatedCompletion existing : simulatedCompletions) {
            if (existing.query.equals(simulated.query)) {
                existing.dueAt = simulated.dueAt;
                existing.domains.clear();
                existing.domains.addAll(simulated.domains);
                return;
            }
        }
        simulatedCompletions.add(simulated);
    }

    private SimulatedCompletion findSimulatedCompletion(String query) {
        String normalized = Text.normalizeQuery(query);
        for (SimulatedCompletion completion : simulatedCompletions) {
            if (completion.query.equals(normalized)) {
                return completion;
            }
        }
        return null;
    }

    /** A response deadline a controlled driver can hand to the search when it simulates the network. */
    private static final class SimulatedCompletion {
        String query = "";
        long dueAt = -1L;
        final List<String> domains = new ArrayList<>();
    }
}

