package org.wordpress.benchmark.domains.base;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Bundle;
import android.text.Editable;
import android.text.TextWatcher;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;

import org.json.JSONArray;
import org.json.JSONObject;

/**
 * The "All Domains" screen.
 *
 * <p>It renders the loading, complete, filtered, empty and error states of the account's domain
 * list, offers the local filter and the add-domain route, and opens the contained details screen
 * for a row.</p>
 */
public final class DomainActivity extends Activity
        implements DomainPageOwner.Observer, DomainRouter.Delegate {

    private static final int REQUEST_CHECKOUT = 41;

    private DomainSession session;
    private DomainPageOwner owner;
    private ProgressBar progressView;
    private TextView statusView;
    private EditText filterView;
    private LinearLayout contentView;
    private boolean updatingFilter;

    @Override protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        session = DomainSession.get(this);
        owner = session.owner();
        setContentView(buildScreen());
        owner.addObserver(this);
        owner.openAllDomains();
        render();
    }

    @Override protected void onResume() {
        super.onResume();
        DomainRouter.get().setDelegate(this);
        if (owner.consumeListRefreshRequired()) {
            // A completed or cancelled checkout needs the refreshed list when we come back.
            owner.refreshDomains();
        }
        render();
    }

    @Override protected void onPause() {
        DomainRouter.get().clearDelegate(this);
        super.onPause();
    }

    @Override protected void onDestroy() {
        owner.removeObserver(this);
        super.onDestroy();
    }

    public DomainPageOwner pageOwner() {
        return owner;
    }

    /** Re-reads the owned state and updates the list, the states and the actions. */
    public void render() {
        if (contentView == null) {
            return;
        }
        JSONObject state = owner.snapshot();
        String listState = state.optString("listState", "idle");
        boolean listUsable = state.optBoolean("addDomainEnabled", false);

        progressView.setVisibility("loading".equals(listState) ? View.VISIBLE : View.INVISIBLE);
        statusView.setText(statusText(state, listState));
        filterView.setEnabled(listUsable);
        String query = state.optString("query", "");
        if (!query.equals(filterView.getText().toString())) {
            updatingFilter = true;
            filterView.setText(query);
            updatingFilter = false;
        }
        contentView.removeAllViews();
        if ("error".equals(listState)) {
            contentView.addView(buildErrorState(state));
            return;
        }
        if ("empty".equals(listState)) {
            contentView.addView(buildEmptyState());
            return;
        }
        JSONArray rows = state.optJSONArray("visibleDomainRows");
        if (rows == null || rows.length() == 0) {
            if (!"loading".equals(listState)) {
                contentView.addView(buildEmptyState());
            }
            return;
        }
        for (int index = 0; index < rows.length(); index++) {
            JSONObject row = rows.optJSONObject(index);
            if (row != null) {
                contentView.addView(buildRow(row));
            }
        }
    }

    @Override public void onDomainStateChanged() {
        runOnUiThread(new Runnable() {
            @Override public void run() {
                render();
            }
        });
    }

    // ---------------------------------------------------------------- view building

    private View buildScreen() {
        LinearLayout screen = new LinearLayout(this);
        screen.setOrientation(LinearLayout.VERTICAL);
        screen.setPadding(32, 32, 32, 32);

        LinearLayout toolbar = new LinearLayout(this);
        toolbar.setOrientation(LinearLayout.HORIZONTAL);
        toolbar.setGravity(Gravity.CENTER_VERTICAL);
        TextView title = new TextView(this);
        title.setText("All Domains");
        title.setTextSize(26);
        title.setTypeface(Typeface.DEFAULT_BOLD);
        toolbar.addView(title, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
        Button addDomain = new Button(this);
        addDomain.setText("Find a domain");
        addDomain.setEnabled(listUsableForToolbar());
        addDomain.setOnClickListener(new View.OnClickListener() {
            @Override public void onClick(View view) {
                owner.tapAddDomain();
            }
        });
        toolbar.addView(addDomain);
        screen.addView(toolbar);

        progressView = new ProgressBar(this);
        progressView.setIndeterminate(true);
        screen.addView(progressView);

        statusView = new TextView(this);
        statusView.setPadding(0, 16, 0, 16);
        screen.addView(statusView);

        filterView = new EditText(this);
        filterView.setHint("Search your domains");
        filterView.setSingleLine(true);
        filterView.addTextChangedListener(new TextWatcher() {
            @Override public void beforeTextChanged(CharSequence text, int start, int count, int after) { }

            @Override public void onTextChanged(CharSequence text, int start, int before, int count) { }

            @Override public void afterTextChanged(Editable editable) {
                if (updatingFilter) {
                    return;
                }
                owner.onLocalFilterChanged(editable == null ? "" : editable.toString());
            }
        });
        screen.addView(filterView, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));

        ScrollView scroller = new ScrollView(this);
        contentView = new LinearLayout(this);
        contentView.setOrientation(LinearLayout.VERTICAL);
        scroller.addView(contentView, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        screen.addView(scroller, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f));
        return screen;
    }

    private View buildRow(final JSONObject row) {
        LinearLayout item = new LinearLayout(this);
        item.setOrientation(LinearLayout.VERTICAL);
        item.setPadding(0, 24, 0, 24);

        TextView domain = new TextView(this);
        domain.setText(row.optString("domain", ""));
        domain.setTextSize(18);
        domain.setTypeface(Typeface.DEFAULT_BOLD);
        item.addView(domain);

        TextView site = new TextView(this);
        site.setText(row.optString("siteTitle", ""));
        site.setTextSize(15);
        item.addView(site);

        TextView status = new TextView(this);
        String statusText = row.optString("status", "");
        String expiry = row.optString("expiry", "");
        status.setText(Text.isBlank(expiry) ? statusText : statusText + " · expires " + expiry);
        status.setTextSize(13);
        item.addView(status);

        Button details = new Button(this);
        details.setText("Domain details");
        details.setOnClickListener(new View.OnClickListener() {
            @Override public void onClick(View view) {
                JSONObject payload = Json.object();
                Json.put(payload, "domain", row.optString("domain", ""));
                Json.put(payload, "managedDomain", row.optString("domain", ""));
                Json.put(payload, "currentUrl", row.optString("detailsUrl", ""));
                owner.openDetails(payload);
            }
        });
        item.addView(details);
        return item;
    }

    private View buildEmptyState() {
        LinearLayout empty = new LinearLayout(this);
        empty.setOrientation(LinearLayout.VERTICAL);
        empty.setPadding(0, 48, 0, 48);
        TextView message = new TextView(this);
        message.setText("You do not have any domains yet. Find a domain to get started.");
        message.setTextSize(16);
        empty.addView(message);
        Button findDomain = new Button(this);
        findDomain.setText("Find a domain");
        findDomain.setOnClickListener(new View.OnClickListener() {
            @Override public void onClick(View view) {
                owner.tapFindDomain();
            }
        });
        empty.addView(findDomain);
        return empty;
    }

    private View buildErrorState(JSONObject state) {
        LinearLayout error = new LinearLayout(this);
        error.setOrientation(LinearLayout.VERTICAL);
        error.setPadding(0, 48, 0, 48);
        TextView message = new TextView(this);
        String reason = state.optString("listError", "");
        message.setText(Text.isBlank(reason) ? "Your domains could not be loaded." : reason);
        message.setTextSize(16);
        error.addView(message);
        Button retry = new Button(this);
        retry.setText("Retry");
        retry.setOnClickListener(new View.OnClickListener() {
            @Override public void onClick(View view) {
                owner.retryCurrentScreen();
            }
        });
        error.addView(retry);
        return error;
    }

    private String statusText(JSONObject state, String listState) {
        if ("loading".equals(listState)) {
            return "Loading your domains…";
        }
        if ("error".equals(listState)) {
            return "Your domains could not be loaded.";
        }
        if ("empty".equals(listState)) {
            return "No domains yet";
        }
        int visible = state.optInt("domainCount", 0);
        int total = state.optInt("accountDomainCount", 0);
        if ("filtered".equals(listState)) {
            return visible + " of " + total + " domains match “" + state.optString("query", "") + "”";
        }
        return visible == total
                ? total + (total == 1 ? " domain" : " domains")
                : visible + " of " + total + " domains";
    }

    private boolean listUsableForToolbar() {
        return true;
    }

    // ---------------------------------------------------------------- effect handling

    @Override public void openDomainSearch() {
        startActivity(new Intent(this, DomainSearchActivity.class));
    }

    @Override public void openDomainPurchase() {
        startActivity(new Intent(this, DomainRegistrationActivity.class));
    }

    @Override public void openCheckout(String checkoutToken, String checkoutUrl) {
        Intent checkout = new Intent(this, DomainCheckoutActivity.class);
        checkout.putExtra(DomainCheckoutActivity.EXTRA_CHECKOUT_TOKEN, checkoutToken);
        checkout.putExtra(DomainCheckoutActivity.EXTRA_CHECKOUT_URL, checkoutUrl);
        checkout.putExtra(DomainCheckoutActivity.EXTRA_DOMAIN, owner.checkoutDomain());
        checkout.putExtra(DomainCheckoutActivity.EXTRA_EMAIL, owner.checkoutEmail());
        startActivityForResult(checkout, REQUEST_CHECKOUT);
    }

    @Override public void openPlans(String site, String domain) {
        showMessage("Adding " + domain + " to " + site + " needs one of the eligible plans");
    }

    @Override public void openDomainDetails(String domain, String url) {
        Intent details = new Intent(this, DomainDetailsWebViewActivity.class);
        details.putExtra(DomainDetailsWebViewActivity.EXTRA_DOMAIN, domain);
        details.putExtra(DomainDetailsWebViewActivity.EXTRA_URL, url);
        startActivity(details);
    }

    @Override public void openExternalUrl(String url) {
        if (Text.isBlank(url)) {
            return;
        }
        try {
            startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(url)));
        } catch (Exception error) {
            showMessage("No app can open " + url);
        }
    }

    @Override public void closeTransientScreens() {
        // The all-domains screen is the root of the flow.
    }

    @Override public void showMessage(String message) {
        if (Text.isBlank(message)) {
            return;
        }
        Toast.makeText(this, message, Toast.LENGTH_LONG).show();
    }

    @Override protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == REQUEST_CHECKOUT) {
            owner.onCheckoutResult(data, resultCode);
        }
    }
}

