/**
     * Records the network deadline of a suggestions request.
     *
     * <p>Only the delivery time comes from here; the proposals themselves always come from the
     * backend response, so no simulated response can stand in for a real one.</p>
     */
    private void registerResponseDeadline(String ownerQuery, JSONObject completion) {
        if (completion == null) {
            return;
        }
        String query = Text.normalizeQuery(Text.isBlank(ownerQuery)
                ? Text.first(completion, new String[] { "query", "searchQuery" })
                : ownerQuery);
        if (query.isEmpty()) {
            return;
        }
        long dueAt = Text.firstLong(completion, new String[] { "atMs", "at", "dueAtMs", "responseAtMs" }, -1L);
        if (dueAt < 0L) {
            return;
        }
        for (Map.Entry<String, Long> entry : responseDeadlines.entrySet()) {
            if (entry.getKey().equals(query)) {
                entry.setValue(dueAt);
                return;
            }
        }
        responseDeadlines.put(query, dueAt);
    }

    private long responseDueAt(String query) {
        Long dueAt = responseDeadlines.get(Text.normalizeQuery(query));
        return dueAt == null ? -1L : dueAt;
    }
}

