/** The sites an existing domain can be attached to; they are loaded once, off the page thread. */
    public JSONArray sites() {
        if (sitesLoaded) {
            return loadedSites;
        }
        final Backend currentBackend = backend;
        if (currentBackend == null) {
            sitesLoaded = true;
            return loadedSites;
        }
        scheduler.executeOnWorker(new Runnable() {
            @Override public void run() {
                JSONArray fetched = Json.array();
                try {
                    JSONArray sites = currentBackend.fetchSites();
                    if (sites != null) {
                        fetched = sites;
                    }
                } catch (Exception error) {
                    emit("sitesUnavailable", "message", Text.orEmpty(String.valueOf(error.getMessage())));
                }
                final JSONArray result = fetched;
                scheduler.post(new Runnable() {
                    @Override public void run() {
                        loadedSites = result;
                        sitesLoaded = true;
                        emit("sitesLoaded", "sites", loadedSites.length());
                        notifyObservers();
                    }
                });
            }
        });
        return loadedSites;
    }

