/** Retry repeats whichever operation produced the visible error. */
    public void retryCurrentScreen() {
        if (listState == LIST_ERROR && !detailsScreenOpen && !checkoutScreenOpen) {
            retryList();
            return;
        }
        if (searchState == SEARCH_ERROR) {
            retrySearch();
            return;
        }
        if (cartState == CART_ERROR) {
            // The failure is acknowledged first, which keeps the selected proposal for the retry.
            acknowledgeCartError();
            submitCart();
            return;
        }
        if (checkoutState == CHECKOUT_ERROR) {
            // The checkout could not be completed; the cart is still there to continue from.
            retryCheckout();
            return;
        }
        emit("retryIgnored", "listState", listState, "searchState", searchState, "cartState", cartState);
    }

