/**
     * Applies a suggestions payload that arrived outside the debounced search, for example a
     * suggestions response that was already in flight when the search screen opened.
     */
private void applySearchResultsPayload(JSONObject payload) {
        JSONArray suggestions = suggestionsOf(payload);
        if (suggestions == null || suggestions.length() == 0) {
            emit("searchResultsIgnored", "reason", "the payload carries no domain suggestions");
            return;
        }
        registerResponseDeadlines(payload);
        String query = Text.normalizeQuery(firstNonBlank(Text.optString(payload, "query"), searchQuery));
        if (!query.isEmpty()) {
            searchQuery = query;
            queryGeneration++;
        }
        // A delivered response owns the visible results, so any pending debounce is dropped.
        cancelPendingDispatch();
        List<DomainSuggestion> paid = DomainSuggestion.paidProposals(suggestions);
        proposals.clear();
        proposals.addAll(paid);
        searchError = "";
        setSearchState(SEARCH_POPULATED);
        screen = SCREEN_DOMAIN_SEARCH;
        destination = DESTINATION_DOMAIN_SEARCH;
        emit("searchResults",
                "query", searchQuery,
                "proposals", proposals.size(),
                "excludedFreeSuggestions", countFreeSuggestions(suggestions));
        notifyObservers();
    }

input.newString:
/**
 * A suggestions response is always applied through the same path, so an in-flight answer and a
 * directly supplied payload end up in exactly the same state.
 */
private void applySearchResultsPayload(JSONObject payload) {
        if (payload == null) {
            return;
        }
        String query = Text.normalizeQuery(firstNonBlank(Text.optString(payload, "query"), searchQuery));
        if (query.isEmpty()) {
            emit("searchResultsIgnored", "reason", "the payload names no query");
            return;
        }
        applySearchResponse(queryGeneration, query, payload);
    }

